# -*- coding: utf-8 -*-
"""完整 1m + 5m 8:2 融合训练脚本。

这个文件是 82fusion 的最终训练入口，不只是打包已有模型：

1. 训练 1分钟子模型；
2. 训练 5分钟子模型；
3. 把两个子模型按 8:2 写入一个融合版 model.json。

默认训练轮数为了控制总耗时：

- 1m: FUSION_EPOCHS_1M=5
- 5m: FUSION_EPOCHS_5M=3

如果平台/本地机器较慢，可以用环境变量进一步降训练轮数或限制股票数做烟测。
正式提交不要设置 MAX_LOCAL_INSTRUMENTS。
"""

from __future__ import annotations

import json
import os
import sys
import time
import types
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parent if "__file__" in globals() else Path.cwd()
PROJECT_ROOT = ROOT.parent
OUTPUT_PATH = Path(os.environ.get("FUSION_MODEL_PATH", ROOT / "model.json"))
TEMP_DIR = ROOT / "_fusion_submodels"

WEIGHT_1M = float(os.environ.get("FUSION_WEIGHT_1M", "0.8"))
WEIGHT_5M = float(os.environ.get("FUSION_WEIGHT_5M", "0.2"))
EPOCHS_1M = int(os.environ.get("FUSION_EPOCHS_1M", "5"))
EPOCHS_5M = int(os.environ.get("FUSION_EPOCHS_5M", "3"))
TIME_BUDGET_SECONDS = int(os.environ.get("FUSION_TIME_BUDGET_SECONDS", str(4 * 60 * 60)))

SOURCE_1M = '# -*- coding: utf-8 -*-\n"""Standalone diff-mLANet style training file for BigAlpha.\n\n这个文件刻意做成单文件自包含：转成 train.ipynb 后，只需要配套\ninfer.ipynb 和 model.json，不再依赖 diff_mlanet_arch.py、layers/ 或项目根目录\n里的其它 Python 文件。\n"""\n\nfrom __future__ import annotations\n\nimport glob\nimport json\nimport math\nimport os\nimport random\nimport time\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom torch.utils.data import DataLoader, TensorDataset\n\ntry:\n    import dai\nexcept ModuleNotFoundError:\n    try:\n        from bigquant import dai\n    except ModuleNotFoundError:\n        dai = None\n\n\nROOT = Path(__file__).resolve().parent if "__file__" in globals() else Path.cwd()\nPROJECT_ROOT = ROOT.parent\nMODEL_PATH = Path(os.environ.get("DIFFMLANET_MODEL_PATH", ROOT / "model.json"))\n\nPUBLIC_TRAIN_START = "2019-01-01"\nPUBLIC_TRAIN_END = "2023-12-31 23:59:59"\nSEQ_LEN = 64\nSEED = int(os.environ.get("DIFFMLANET_SEED", "42"))\nEPOCHS = int(os.environ.get("DIFFMLANET_EPOCHS", "5"))\nBATCH = int(os.environ.get("DIFFMLANET_BATCH", "512"))\nLR = float(os.environ.get("DIFFMLANET_LR", "0.001"))\n\nLOCAL_DATA_PATH = os.environ.get(\n    "LOCAL_DATA_PATH",\n    str(PROJECT_ROOT / "local_data/e2e_bar1m_train_2019_2023"),\n)\nLOCAL_TRAIN_START = os.environ.get("LOCAL_TRAIN_START", PUBLIC_TRAIN_START)\nLOCAL_TRAIN_END = os.environ.get("LOCAL_TRAIN_END", PUBLIC_TRAIN_END)\nMAX_LOCAL_INSTRUMENTS = int(os.environ.get("MAX_LOCAL_INSTRUMENTS", "0"))\nTRAIN_CHUNK = int(os.environ.get("DIFFMLANET_TRAIN_CHUNK", "20"))\nMAX_TRAIN_INSTRUMENTS = int(os.environ.get("DIFFMLANET_MAX_TRAIN_INSTRUMENTS", "0"))\n\n# 比赛适配：默认训练每日截面 rank 标签，而不是直接拟合原始收益率。\n# 这样更贴近公榜/私榜中的每日截面排序目标。\nLABEL_MODE = os.environ.get("DIFFMLANET_LABEL_MODE", "daily_rank").lower()\nMIN_RANK_DAY_SAMPLES = int(os.environ.get("DIFFMLANET_MIN_RANK_DAY_SAMPLES", "100"))\nLOSS_NAME = os.environ.get("DIFFMLANET_LOSS", "smooth_l1").lower()\nSMOOTH_L1_BETA = float(os.environ.get("DIFFMLANET_SMOOTH_L1_BETA", "0.02"))\n\n# 比赛合规改进：不引入人工特征分支，只在训练目标和模型选择上优化。\n# 默认用 2023 年做验证集，每轮按验证 RankIC 保存最佳模型。\nUSE_VALIDATION = os.environ.get("DIFFMLANET_USE_VALIDATION", "1") != "0"\nVALID_START = os.environ.get("DIFFMLANET_VALID_START", "2023-01-01")\nVALID_END = os.environ.get("DIFFMLANET_VALID_END", "2023-12-31 23:59:59")\nIC_LOSS_ALPHA = float(os.environ.get("DIFFMLANET_IC_LOSS_ALPHA", "0.05"))\nMIN_IC_DAY_SAMPLES = int(os.environ.get("DIFFMLANET_MIN_IC_DAY_SAMPLES", "100"))\n\n\nOHLC_COLS = ["high", "open", "low", "close"]\nASK_PRICE_COLS = [f"ask_price{i}" for i in range(1, 4)]\nBID_PRICE_COLS = [f"bid_price{i}" for i in range(1, 4)]\nASK_VOLUME_COLS = [f"ask_volume{i}" for i in range(1, 4)]\nBID_VOLUME_COLS = [f"bid_volume{i}" for i in range(1, 4)]\nASK_ORDER_COLS = [f"ask_num_orders{i}" for i in range(1, 4)]\nBID_ORDER_COLS = [f"bid_num_orders{i}" for i in range(1, 4)]\nPRICE_COLS = OHLC_COLS + ASK_PRICE_COLS + BID_PRICE_COLS\nLOG1P_COLS = (\n    ["deal_number", "volume", "amount"]\n    + ASK_VOLUME_COLS\n    + BID_VOLUME_COLS\n    + ASK_ORDER_COLS\n    + BID_ORDER_COLS\n)\nFEATURE_COLS = (\n    ["adjust_factor"]\n    + OHLC_COLS\n    + ["deal_number", "volume", "amount"]\n    + ASK_PRICE_COLS\n    + BID_PRICE_COLS\n    + ASK_VOLUME_COLS\n    + BID_VOLUME_COLS\n    + ASK_ORDER_COLS\n    + BID_ORDER_COLS\n)\nFEATURE_SCHEMA_VERSION = "e2e_bar1m_full_3level_v1"\n\n\ndef log(message: str, **kwargs: Any) -> None:\n    extra = " ".join(f"{key}={value}" for key, value in kwargs.items())\n    print(f"[diffMLANet][train] {message}" + (f" {extra}" if extra else ""))\n\n\ndef seed_everything(seed: int = SEED) -> None:\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed_all(seed)\n\n\ndef full_day_bounds(start_date: str, end_date: str) -> tuple[str, str]:\n    start = pd.Timestamp(start_date).normalize()\n    end = pd.Timestamp(end_date).normalize() + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)\n    return start.strftime("%Y-%m-%d %H:%M:%S"), end.strftime("%Y-%m-%d %H:%M:%S")\n\n\ndef to_canonical(df: pd.DataFrame, *, is_local: bool) -> pd.DataFrame:\n    df = df.copy()\n    df["date"] = pd.to_datetime(df["date"])\n    if is_local:\n        # 本地 parquet 中价格类字段可能用 -1 表示缺失。\n        # 需要先把所有价格字段的 -1 置空，再做 /100 缩放，避免 -1 被错误变成 -0.01。\n        for col in PRICE_COLS:\n            if col in df.columns:\n                df.loc[df[col] == -1, col] = np.nan\n        for col in PRICE_COLS + ["amount"]:\n            if col in df.columns:\n                df[col] = df[col].astype("float64") / 100.0\n        if "instrument" not in df.columns:\n            df["instrument"] = df["instrument_id"].astype(str)\n    else:\n        df["instrument"] = df["instrument"].astype(str)\n\n    missing = [col for col in FEATURE_COLS if col not in df.columns]\n    if missing:\n        raise ValueError(f"输入数据缺少模型字段: {missing}")\n    return (\n        df[["date", "instrument"] + FEATURE_COLS]\n        .dropna(subset=["date", "instrument"])\n        .sort_values(["instrument", "date"])\n        .reset_index(drop=True)\n    )\n\n\ndef _prepare_one_day(day_df: pd.DataFrame) -> tuple[np.ndarray, float] | None:\n    day_df = day_df.sort_values("date")\n    if len(day_df) < SEQ_LEN:\n        return None\n    feature_df = day_df[FEATURE_COLS].copy()\n    for col in LOG1P_COLS:\n        feature_df[col] = np.log1p(pd.to_numeric(feature_df[col], errors="coerce").clip(lower=0))\n    feature_df = feature_df.replace([np.inf, -np.inf], np.nan).ffill().fillna(0.0)\n    window = feature_df.iloc[-SEQ_LEN:].to_numpy(dtype=np.float32)\n    close = pd.to_numeric(day_df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()\n    close_value = float(close.iloc[-1]) if len(close) else np.nan\n    return window, close_value\n\n\ndef build_samples(\n    df: pd.DataFrame,\n    *,\n    start_date: str,\n    end_date: str,\n    mode: str,\n    instruments: list[str] | None = None,\n    stats: tuple[np.ndarray, np.ndarray] | None = None,\n    normalize: bool = True,\n) -> tuple[np.ndarray, np.ndarray | None, pd.DataFrame, tuple[np.ndarray, np.ndarray] | None]:\n    start_ts = pd.Timestamp(start_date)\n    end_ts = pd.Timestamp(end_date)\n    data = df[(df["date"] >= start_ts) & (df["date"] <= end_ts)].copy()\n    if instruments is not None:\n        wanted = {str(item) for item in instruments}\n        data = data[data["instrument"].astype(str).isin(wanted)]\n    if data.empty:\n        raise RuntimeError(f"指定区间没有数据: {start_date} ~ {end_date}")\n\n    windows: list[np.ndarray] = []\n    labels: list[np.float32] = []\n    keys: list[tuple[pd.Timestamp, str]] = []\n    for instrument, instrument_df in data.groupby("instrument", sort=False):\n        daily: list[tuple[pd.Timestamp, np.ndarray, float]] = []\n        for day, day_df in instrument_df.groupby(instrument_df["date"].dt.normalize(), sort=True):\n            prepared = _prepare_one_day(day_df)\n            if prepared is not None:\n                window, close = prepared\n                daily.append((pd.Timestamp(day), window, close))\n        for index, (day, window, close) in enumerate(daily):\n            label = None\n            if index + 1 < len(daily):\n                next_close = daily[index + 1][2]\n                if np.isfinite(close) and np.isfinite(next_close) and close > 0:\n                    value = next_close / close - 1.0\n                    if np.isfinite(value):\n                        label = np.float32(value)\n            if mode == "train" and label is None:\n                continue\n            windows.append(window)\n            keys.append((day, str(instrument)))\n            if mode == "train":\n                labels.append(label)\n\n    if not windows:\n        raise RuntimeError(f"没有构造出样本: mode={mode}, {start_date} ~ {end_date}")\n    X = np.stack(windows).astype(np.float32)\n    if stats is None and mode == "train":\n        flat = X.reshape(-1, len(FEATURE_COLS))\n        stats = (\n            flat.mean(axis=0, dtype=np.float64).astype(np.float32),\n            (flat.std(axis=0, dtype=np.float64) + 1e-6).astype(np.float32),\n        )\n    if normalize:\n        if stats is None:\n            raise ValueError("推理或标准化时必须提供训练集 stats")\n        mean, std = stats\n        X = ((X - mean) / std).astype(np.float32)\n    index_df = pd.DataFrame(keys, columns=["date", "instrument"])\n    y = np.asarray(labels, dtype=np.float32) if mode == "train" else None\n    return X, y, index_df, stats\n\n\n\n@dataclass\nclass DiffMLANetConfig:\n    n_feat: int = 26\n    seq_len: int = 64\n    d_model: int = 128\n    conv_windows: list[int] = field(default_factory=lambda: [4, 8, 16, 32, 64])\n    conv_channels: int = 96\n    dropout: float = 0.2\n    aeccm_inplanes: int = 8\n    aeccm_ratio: float = 0.5\n    aeccm_low_rank_ratio: float = 0.25\n    diffusion_enabled: bool = True\n    diffusion_steps: int = 128\n    diffusion_beta_start: float = 1e-4\n    diffusion_beta_end: float = 0.02\n    diffusion_hidden_dim: int = 64\n    diffusion_time_dim: int = 64\n    diffusion_num_blocks: int = 2\n    diffusion_inference_step: int = 64\n    diffusion_denoise_eta: float = 0.2\n    lambda_diff: float = 0.01\n\n\nclass RevIN(nn.Module):\n    def __init__(self, num_variates: int, eps: float = 1e-5):\n        super().__init__()\n        self.eps = eps\n        self.gamma = nn.Parameter(torch.ones(1, num_variates, 1))\n        self.beta = nn.Parameter(torch.zeros(1, num_variates, 1))\n\n    def forward(self, x: torch.Tensor):\n        x_feature = x.permute(0, 2, 1)\n        mean = x_feature.mean(dim=-1, keepdim=True)\n        var = x_feature.var(dim=-1, unbiased=False, keepdim=True)\n        normalized = (x_feature - mean) * var.clamp(min=self.eps).rsqrt()\n        scaled = normalized * self.gamma + self.beta\n        return scaled.permute(0, 2, 1)\n\n\nclass SinusoidalTimeEmbedding(nn.Module):\n    """re-mLANet4 diffusion time embedding, inlined for two-file submission."""\n\n    def __init__(self, dim: int):\n        super().__init__()\n        self.dim = dim\n\n    def forward(self, timesteps: torch.Tensor) -> torch.Tensor:\n        device = timesteps.device\n        half_dim = self.dim // 2\n        if half_dim == 0:\n            return timesteps.float().unsqueeze(-1)\n        scale = math.log(10000) / max(half_dim - 1, 1)\n        freqs = torch.exp(torch.arange(half_dim, device=device) * -scale)\n        args = timesteps.float().unsqueeze(1) * freqs.unsqueeze(0)\n        emb = torch.cat([args.sin(), args.cos()], dim=1)\n        if self.dim % 2 == 1:\n            emb = F.pad(emb, (0, 1))\n        return emb\n\n\ndef _group_count(channels: int, max_groups: int = 8) -> int:\n    for groups in range(min(max_groups, channels), 0, -1):\n        if channels % groups == 0:\n            return groups\n    return 1\n\n\nclass ResidualConvBlock(nn.Module):\n    """Residual 1D conv block used by the re-mLANet4 diffusion denoiser."""\n\n    def __init__(self, channels: int, time_dim: int, dilation: int = 1):\n        super().__init__()\n        padding = dilation\n        groups = _group_count(channels)\n        self.norm1 = nn.GroupNorm(groups, channels)\n        self.conv1 = nn.Conv1d(channels, channels, kernel_size=3, padding=padding, dilation=dilation)\n        self.time_proj = nn.Linear(time_dim, channels)\n        self.norm2 = nn.GroupNorm(groups, channels)\n        self.conv2 = nn.Conv1d(channels, channels, kernel_size=3, padding=padding, dilation=dilation)\n        self.act = nn.SiLU()\n\n    def forward(self, x: torch.Tensor, time_emb: torch.Tensor) -> torch.Tensor:\n        residual = x\n        x = self.conv1(self.act(self.norm1(x)))\n        x = x + self.time_proj(time_emb).unsqueeze(-1)\n        x = self.conv2(self.act(self.norm2(x)))\n        return x + residual\n\n\nclass DiffusionDenoiser(nn.Module):\n    """Lightweight DDPM noise predictor copied from re-mLANet4 and kept self-contained."""\n\n    def __init__(\n        self,\n        seq_len: int,\n        enc_in: int,\n        num_steps: int = 128,\n        beta_start: float = 1e-4,\n        beta_end: float = 0.02,\n        hidden_dim: int = 64,\n        time_dim: int = 64,\n        num_blocks: int = 2,\n        inference_step: int | None = None,\n    ):\n        super().__init__()\n        self.seq_len = seq_len\n        self.enc_in = enc_in\n        self.num_steps = num_steps\n        self.inference_step = num_steps // 2 if inference_step is None else inference_step\n\n        betas = torch.linspace(beta_start, beta_end, num_steps, dtype=torch.float32)\n        alphas = 1.0 - betas\n        alpha_bars = torch.cumprod(alphas, dim=0)\n        self.register_buffer("betas", betas, persistent=False)\n        self.register_buffer("alphas", alphas, persistent=False)\n        self.register_buffer("alpha_bars", alpha_bars, persistent=False)\n\n        self.time_mlp = nn.Sequential(\n            SinusoidalTimeEmbedding(time_dim),\n            nn.Linear(time_dim, time_dim),\n            nn.SiLU(),\n            nn.Linear(time_dim, time_dim),\n        )\n        self.input_proj = nn.Conv1d(1, hidden_dim, kernel_size=3, padding=1)\n        self.blocks = nn.ModuleList(\n            [ResidualConvBlock(hidden_dim, time_dim, dilation=2 ** (idx % 3)) for idx in range(num_blocks)]\n        )\n        self.output_norm = nn.GroupNorm(_group_count(hidden_dim), hidden_dim)\n        self.output_proj = nn.Conv1d(hidden_dim, 1, kernel_size=3, padding=1)\n        self.act = nn.SiLU()\n\n    def _extract(self, values: torch.Tensor, timesteps: torch.Tensor, x: torch.Tensor) -> torch.Tensor:\n        gathered = values.gather(0, timesteps).to(device=x.device, dtype=x.dtype)\n        return gathered.view(-1, 1, 1)\n\n    def _expand_timesteps(self, timesteps: torch.Tensor, channels: int) -> torch.Tensor:\n        return timesteps.unsqueeze(1).expand(-1, channels).reshape(-1)\n\n    def q_sample(\n        self,\n        x0: torch.Tensor,\n        timesteps: torch.Tensor,\n        noise: torch.Tensor | None = None,\n    ) -> tuple[torch.Tensor, torch.Tensor]:\n        if noise is None:\n            noise = torch.randn_like(x0)\n        sqrt_alpha_bar = self._extract(self.alpha_bars.sqrt(), timesteps, x0)\n        sqrt_one_minus_alpha_bar = self._extract((1.0 - self.alpha_bars).sqrt(), timesteps, x0)\n        return sqrt_alpha_bar * x0 + sqrt_one_minus_alpha_bar * noise, noise\n\n    def predict_noise(self, x_t: torch.Tensor, timesteps: torch.Tensor) -> torch.Tensor:\n        batch, length, channels = x_t.shape\n        x = x_t.permute(0, 2, 1).reshape(batch * channels, 1, length)\n        time_emb = self.time_mlp(self._expand_timesteps(timesteps, channels))\n\n        x = self.input_proj(x)\n        for block in self.blocks:\n            x = block(x, time_emb)\n        x = self.output_proj(self.act(self.output_norm(x)))\n        return x.reshape(batch, channels, length).permute(0, 2, 1)\n\n    def predict_clean_from_noise(\n        self,\n        x_t: torch.Tensor,\n        timesteps: torch.Tensor,\n        pred_noise: torch.Tensor,\n    ) -> torch.Tensor:\n        sqrt_alpha_bar = self._extract(self.alpha_bars.sqrt(), timesteps, x_t)\n        sqrt_one_minus_alpha_bar = self._extract((1.0 - self.alpha_bars).sqrt(), timesteps, x_t)\n        return (x_t - sqrt_one_minus_alpha_bar * pred_noise) / sqrt_alpha_bar.clamp(min=1e-8)\n\n    def training_loss(\n        self,\n        x0: torch.Tensor,\n        timesteps: torch.Tensor | None = None,\n        noise: torch.Tensor | None = None,\n    ) -> dict[str, torch.Tensor]:\n        batch = x0.shape[0]\n        if timesteps is None:\n            timesteps = torch.randint(0, self.num_steps, (batch,), device=x0.device)\n        x_t, noise = self.q_sample(x0, timesteps, noise)\n        pred_noise = self.predict_noise(x_t, timesteps)\n        loss = F.mse_loss(pred_noise, noise)\n        x_clean = self.predict_clean_from_noise(x_t, timesteps, pred_noise)\n        return {\n            "loss": loss,\n            "x_clean": x_clean,\n            "x_t": x_t,\n            "pred_noise": pred_noise,\n            "noise": noise,\n            "timesteps": timesteps,\n        }\n\n    def denoise(self, x_t: torch.Tensor, timesteps: torch.Tensor | None = None) -> torch.Tensor:\n        batch = x_t.shape[0]\n        if timesteps is None:\n            step = max(0, min(int(self.inference_step), self.num_steps - 1))\n            timesteps = torch.full((batch,), step, device=x_t.device, dtype=torch.long)\n        pred_noise = self.predict_noise(x_t, timesteps)\n        return self.predict_clean_from_noise(x_t, timesteps, pred_noise)\n\n    def forward(\n        self,\n        x: torch.Tensor,\n        return_loss: bool = False,\n        timesteps: torch.Tensor | None = None,\n    ) -> torch.Tensor | tuple[torch.Tensor, torch.Tensor]:\n        if return_loss:\n            diffusion = self.training_loss(x, timesteps=timesteps)\n            return diffusion["x_clean"], diffusion["loss"]\n        return self.denoise(x, timesteps=timesteps)\n\n\ndef split_window_chains(windows: list[int]) -> list[list[int]]:\n    """Same divisibility-chain idea as re-mLANet4/layers/PyramidalRNNEmbedding.py."""\n    windows = sorted(int(item) for item in windows)\n    used = np.zeros(len(windows), dtype=np.int8)\n    chains: list[list[int]] = []\n    while used.sum() < len(windows):\n        chain = []\n        last = None\n        for index in range(len(windows) - 1, -1, -1):\n            value = windows[index]\n            if used[index] == 0 or index == 0:\n                if last is None:\n                    chain.append(value)\n                    used[index] = 1\n                    last = value\n                elif last % value == 0:\n                    chain.append(value)\n                    used[index] = 1\n                    last = value\n        if chain:\n            chains.append(sorted(chain))\n    return chains\n\n\ndef count_chain_windows(chains: list[list[int]]) -> int:\n    return sum(len(chain) for chain in chains)\n\n\nclass ConvRNNBlock(nn.Module):\n    def __init__(self, kernel: int, conv_channels: int, hidden_size: int):\n        super().__init__()\n        self.conv = nn.Conv1d(1 if kernel == 0 else conv_channels, conv_channels, kernel_size=max(1, kernel), stride=max(1, kernel))\n        self.gru = nn.GRU(conv_channels, hidden_size, batch_first=True)\n\n    def forward_conv(self, x: torch.Tensor) -> torch.Tensor:\n        return self.conv(x)\n\n    def forward_rnn(self, x: torch.Tensor) -> torch.Tensor:\n        _, hidden = self.gru(x.permute(0, 2, 1))\n        return hidden[-1]\n\n\nclass PyramidalRNNEmbedding(nn.Module):\n    """re-mLANet4 PRE: pyramidal convolution chains with GRU summaries."""\n\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        self.config = config\n        self.chains = split_window_chains(config.conv_windows)\n        window_count = count_chain_windows(self.chains)\n        self.rate = nn.Parameter(torch.ones(window_count, 1) / max(window_count, 1))\n        self.temperature = 0.002\n\n        counts = {window: 0 for window in config.conv_windows}\n        for chain in self.chains:\n            for window in chain:\n                counts[window] += 1\n        base_hidden = max(1, config.d_model // len(config.conv_windows))\n        self.hidden_by_window = {\n            window: max(1, base_hidden // max(counts[window], 1))\n            for window in config.conv_windows\n        }\n        out_dim = sum(self.hidden_by_window[window] for chain in self.chains for window in chain)\n\n        modules = []\n        for chain in self.chains:\n            chain_blocks = []\n            previous_window = 1\n            for position, window in enumerate(chain):\n                kernel = int(window / previous_window)\n                hidden = self.hidden_by_window[window]\n                block = nn.ModuleDict(\n                    {\n                        "conv": nn.Conv1d(\n                            1 if position == 0 else config.conv_channels,\n                            config.conv_channels,\n                            kernel_size=max(1, kernel),\n                            stride=max(1, kernel),\n                        ),\n                        "gru": nn.GRU(config.conv_channels, hidden, batch_first=True),\n                    }\n                )\n                chain_blocks.append(block)\n                previous_window = window\n            modules.append(nn.ModuleList(chain_blocks))\n        self.chain_modules = nn.ModuleList(modules)\n        self.out = nn.Linear(out_dim, config.d_model)\n        self.dropout = nn.Dropout(config.dropout)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        batch, seq_len, n_feat = x.shape\n        x = x.permute(0, 2, 1).reshape(batch * n_feat, 1, seq_len)\n        summaries = []\n        rate = torch.softmax((self.rate / self.temperature).squeeze(-1), dim=0)\n        rate = rate * rate.numel()\n        rate_index = 0\n\n        for chain, module_list in zip(self.chains, self.chain_modules):\n            conv_map = {}\n            tmp = x\n            for window, block in zip(chain, module_list):\n                tmp = block["conv"](tmp)\n                conv_map[window] = tmp\n\n            last_window = None\n            upscaled = tmp\n            for window, block in reversed(list(zip(chain, module_list))):\n                if last_window is not None:\n                    scale_factor = last_window / window\n                    upscaled = nn.functional.interpolate(upscaled, scale_factor=scale_factor)\n                    diff = upscaled.shape[-1] - conv_map[window].shape[-1]\n                    if diff < 0:\n                        upscaled = nn.functional.pad(upscaled, (0, -diff), mode="replicate")\n                    elif diff > 0:\n                        upscaled = upscaled[:, :, :-diff]\n                    rnn_input = upscaled + conv_map[window]\n                else:\n                    rnn_input = upscaled\n                hidden, _ = block["gru"](rnn_input.permute(0, 2, 1))\n                summary = hidden[:, -1, :].reshape(batch, n_feat, -1)\n                summaries.append(summary * rate[rate_index])\n                rate_index += 1\n                last_window = window\n\n        tokens = torch.cat(summaries, dim=-1)\n        return self.dropout(self.out(tokens))\n\n\nclass AECCM(nn.Module):\n    """re-mLANet4 AECCM: dense context update + low-rank update + fusion gate."""\n\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        if config.d_model % config.aeccm_inplanes != 0:\n            raise ValueError("d_model must be divisible by aeccm_inplanes")\n        self.d_model = config.d_model\n        self.inplanes = config.aeccm_inplanes\n        planes = max(1, int(self.inplanes * config.aeccm_ratio))\n        rank = max(1, int(self.inplanes * config.aeccm_low_rank_ratio))\n        self.conv_mask = nn.Conv2d(self.inplanes, 1, kernel_size=1)\n        self.softmax = nn.Softmax(dim=2)\n        self.channel_add_conv1 = nn.Sequential(\n            nn.Conv2d(self.inplanes, planes, kernel_size=1),\n            nn.LayerNorm([planes, 1, 1]),\n            nn.ReLU(inplace=True),\n            nn.Conv2d(planes, self.inplanes, kernel_size=1),\n        )\n        self.channel_add_conv2 = nn.Sequential(\n            nn.Conv2d(self.inplanes, planes, kernel_size=3, padding=1),\n            nn.LayerNorm([planes, 1, 1]),\n            nn.ReLU(inplace=True),\n            nn.Conv2d(planes, self.inplanes, kernel_size=3, padding=1),\n        )\n        self.low_rank_down = nn.Conv2d(self.inplanes, rank, kernel_size=1, bias=False)\n        self.low_rank_norm = nn.LayerNorm([rank, 1, 1])\n        self.low_rank_mid = nn.Sequential(\n            nn.Conv2d(rank, rank, kernel_size=3, padding=1, groups=rank, bias=False),\n            nn.ReLU(inplace=True),\n            nn.Conv2d(rank, rank, kernel_size=1, bias=False),\n            nn.ReLU(inplace=True),\n        )\n        self.low_rank_up = nn.Conv2d(rank, self.inplanes, kernel_size=1, bias=False)\n        self.fusion_gate = nn.Sequential(nn.Conv2d(self.inplanes * 2, self.inplanes, kernel_size=1), nn.Sigmoid())\n        self.conv1 = nn.Conv2d(self.inplanes, self.inplanes, kernel_size=1)\n\n    def spatial_attention(self, x: torch.Tensor) -> torch.Tensor:\n        batch, channel, tokens, width = x.size()\n        input_x = x.view(batch, channel, tokens * width).unsqueeze(1)\n        context_mask = self.conv_mask(x).view(batch, 1, tokens * width)\n        context_mask = self.softmax(context_mask).unsqueeze(-1)\n        context = torch.matmul(input_x, context_mask)\n        return context.view(batch, channel, 1, 1)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        batch, tokens, _ = x.shape\n        y = x.reshape(batch, self.inplanes, tokens, self.d_model // self.inplanes)\n        spatial_out = self.spatial_attention(y)\n        dense_out = self.conv1(self.channel_add_conv2(spatial_out) + self.channel_add_conv1(spatial_out))\n        low_rank = self.low_rank_up(self.low_rank_mid(self.low_rank_norm(self.low_rank_down(spatial_out))))\n        gate = self.fusion_gate(torch.cat([dense_out, low_rank], dim=1))\n        out = y + dense_out + gate * low_rank\n        return out.reshape(batch, tokens, self.d_model)\n\n\nclass DiffTokenMixer(nn.Module):\n    """Self-contained gated recurrent mixer used instead of external mLSTM files."""\n\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        self.norm = nn.LayerNorm(config.d_model)\n        self.gru = nn.GRU(\n            input_size=config.d_model,\n            hidden_size=config.d_model // 2,\n            batch_first=True,\n            bidirectional=True,\n        )\n        self.gate = nn.Sequential(nn.Linear(config.d_model, config.d_model), nn.Sigmoid())\n        self.ffn = nn.Sequential(\n            nn.Linear(config.d_model, config.d_model * 2),\n            nn.GELU(),\n            nn.Dropout(config.dropout),\n            nn.Linear(config.d_model * 2, config.d_model),\n        )\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        mixed, _ = self.gru(self.norm(x))\n        mixed = mixed * self.gate(x)\n        return x + mixed + self.ffn(mixed)\n\n\nclass DiffMLANetFactorModel(nn.Module):\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        self.config = config\n        self.revin = RevIN(config.n_feat)\n        self.diffusion_enabled = bool(config.diffusion_enabled)\n        self.diffusion_denoise_eta = float(config.diffusion_denoise_eta)\n        self.diffusion_denoiser = None\n        if self.diffusion_enabled:\n            self.diffusion_denoiser = DiffusionDenoiser(\n                seq_len=config.seq_len,\n                enc_in=config.n_feat,\n                num_steps=config.diffusion_steps,\n                beta_start=config.diffusion_beta_start,\n                beta_end=config.diffusion_beta_end,\n                hidden_dim=config.diffusion_hidden_dim,\n                time_dim=config.diffusion_time_dim,\n                num_blocks=config.diffusion_num_blocks,\n                inference_step=config.diffusion_inference_step,\n            )\n        self.embedding = PyramidalRNNEmbedding(config)\n        self.aeccm = AECCM(config)\n        self.mixer1 = DiffTokenMixer(config)\n        self.mixer2 = DiffTokenMixer(config)\n        self.norm = nn.LayerNorm(config.d_model)\n        self.projector = nn.Linear(config.d_model, 1)\n        self.factor_head = nn.Sequential(\n            nn.LayerNorm(config.n_feat * 3),\n            nn.Linear(config.n_feat * 3, config.n_feat * 2),\n            nn.GELU(),\n            nn.Dropout(config.dropout),\n            nn.Linear(config.n_feat * 2, 1),\n        )\n\n    def _apply_diffusion_denoise(self, x: torch.Tensor) -> torch.Tensor:\n        if self.diffusion_denoiser is None:\n            return x\n        x_clean = self.diffusion_denoiser(x)\n        eta = max(0.0, min(float(self.diffusion_denoise_eta), 1.0))\n        return x + eta * (x_clean - x)\n\n    def forward(\n        self,\n        x: torch.Tensor,\n        return_diffusion_loss: bool = False,\n    ) -> torch.Tensor | tuple[torch.Tensor, torch.Tensor]:\n        last_features = x[:, -1, :]\n        normalized = self.revin(x)\n        diffusion_loss = normalized.new_tensor(0.0)\n        if self.diffusion_enabled and self.diffusion_denoiser is not None:\n            if return_diffusion_loss:\n                diffusion_loss = self.diffusion_denoiser.training_loss(normalized)["loss"]\n            normalized = self._apply_diffusion_denoise(normalized)\n        tokens = self.embedding(normalized)\n        tokens = self.aeccm(tokens)\n        tokens = self.mixer2(self.mixer1(tokens))\n        predicted_features = self.projector(self.norm(tokens)).squeeze(-1)\n        diff_features = predicted_features - last_features\n        factor_input = torch.cat([predicted_features, last_features, diff_features], dim=-1)\n        score = self.factor_head(factor_input).squeeze(-1)\n        if return_diffusion_loss:\n            return score, diffusion_loss\n        return score\n\n\ndef model_config() -> DiffMLANetConfig:\n    return DiffMLANetConfig(\n        n_feat=len(FEATURE_COLS),\n        seq_len=SEQ_LEN,\n        d_model=int(os.environ.get("DIFFMLANET_D_MODEL", "128")),\n        conv_windows=[\n            int(item)\n            for item in os.environ.get("DIFFMLANET_CONV_WINDOWS", "4,8,16,32,64").split(",")\n            if item.strip()\n        ],\n        conv_channels=int(os.environ.get("DIFFMLANET_CONV_CHANNELS", "96")),\n        dropout=float(os.environ.get("DIFFMLANET_DROPOUT", "0.2")),\n        diffusion_enabled=os.environ.get("DIFFMLANET_DIFFUSION_ENABLED", "1") != "0",\n        diffusion_steps=int(os.environ.get("DIFFMLANET_DIFFUSION_STEPS", "128")),\n        diffusion_beta_start=float(os.environ.get("DIFFMLANET_DIFFUSION_BETA_START", "0.0001")),\n        diffusion_beta_end=float(os.environ.get("DIFFMLANET_DIFFUSION_BETA_END", "0.02")),\n        diffusion_hidden_dim=int(os.environ.get("DIFFMLANET_DIFFUSION_HIDDEN_DIM", "64")),\n        diffusion_time_dim=int(os.environ.get("DIFFMLANET_DIFFUSION_TIME_DIM", "64")),\n        diffusion_num_blocks=int(os.environ.get("DIFFMLANET_DIFFUSION_NUM_BLOCKS", "2")),\n        diffusion_inference_step=int(os.environ.get("DIFFMLANET_DIFFUSION_INFERENCE_STEP", "64")),\n        diffusion_denoise_eta=float(os.environ.get("DIFFMLANET_DIFFUSION_DENOISE_ETA", "0.2")),\n        lambda_diff=float(os.environ.get("DIFFMLANET_LAMBDA_DIFF", "0.01")),\n    )\n\n\ndef build_model(config: DiffMLANetConfig | dict[str, Any] | None = None) -> DiffMLANetFactorModel:\n    if isinstance(config, dict):\n        base = DiffMLANetConfig()\n        for key, value in config.items():\n            if hasattr(base, key):\n                setattr(base, key, value)\n        config = base\n    elif config is None:\n        config = model_config()\n    return DiffMLANetFactorModel(config)\n\ndef count_trainable_params(model: nn.Module) -> int:\n    return sum(param.numel() for param in model.parameters() if param.requires_grad)\n\n\ndef validate_model_size(model: nn.Module) -> int:\n    count = count_trainable_params(model)\n    if not 100_000 <= count <= 100_000_000:\n        raise RuntimeError(f"模型可训练参数 {count} 不在比赛约束 [100000, 100000000] 内")\n    return count\n\n\ndef save_model_json(\n    model: nn.Module,\n    *,\n    stats: tuple[np.ndarray, np.ndarray],\n    model_path: str | os.PathLike,\n    config: DiffMLANetConfig,\n    metadata: dict[str, Any],\n) -> str:\n    path = Path(model_path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    mean, std = stats\n    payload = {\n        "model_name": "standalone_re_mlanet4_diffusion_factor",\n        "model_cfg": asdict(config),\n        "feature_cols": list(FEATURE_COLS),\n        "feature_schema_version": FEATURE_SCHEMA_VERSION,\n        "stats": {\n            "mean": np.asarray(mean, dtype=np.float32).tolist(),\n            "std": np.asarray(std, dtype=np.float32).tolist(),\n        },\n        "state_dict": {\n            key: value.detach().cpu().numpy().tolist()\n            for key, value in model.state_dict().items()\n        },\n        "metadata": metadata,\n    }\n    path.write_text(json.dumps(payload), encoding="utf-8")\n    return str(path)\n\n\ndef discover_parquet_files(data_path: str) -> list[str]:\n    path = Path(data_path)\n    if path.is_dir():\n        files = sorted((str(item) for item in path.rglob("*.parquet")), key=lambda item: Path(item).name)\n    elif any(char in data_path for char in "*?["):\n        files = sorted(glob.glob(data_path, recursive=True), key=lambda item: Path(item).name)\n    elif path.is_file():\n        files = [str(path)]\n    else:\n        raise FileNotFoundError(f"训练数据路径不存在: {data_path}")\n    if not files:\n        raise FileNotFoundError(f"没有找到 parquet 文件: {data_path}")\n    return files\n\n\ndef _select_local_instruments(first_file: str) -> list[str] | None:\n    if MAX_LOCAL_INSTRUMENTS <= 0:\n        return None\n    first = to_canonical(pd.read_parquet(first_file), is_local=True)\n    instruments = sorted(first["instrument"].dropna().astype(str).unique().tolist())\n    return instruments[:MAX_LOCAL_INSTRUMENTS]\n\n\n\n\ndef _make_daily_rank_labels(\n    y: np.ndarray,\n    index_df: pd.DataFrame,\n    *,\n    min_day_samples: int = MIN_RANK_DAY_SAMPLES,\n) -> tuple[np.ndarray, np.ndarray]:\n    """把原始未来收益转成每日截面 rank 标签。"""\n    frame = index_df.copy().reset_index(drop=True)\n    frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.normalize()\n    frame["_y"] = np.asarray(y, dtype=np.float32)\n    frame["_finite"] = np.isfinite(frame["_y"].to_numpy())\n\n    valid_count = frame.groupby("date")["_finite"].transform("sum")\n    valid = frame["_finite"] & frame["date"].notna() & (valid_count >= int(min_day_samples))\n\n    ranked = pd.Series(np.nan, index=frame.index, dtype="float64")\n    ranked.loc[valid] = frame.loc[valid].groupby("date")["_y"].rank(method="average", pct=True)\n    ranked = (ranked - 0.5) * 2.0\n\n    mask = ranked.notna().to_numpy()\n    if not bool(mask.any()):\n        raise RuntimeError(f"每日 rank 标签构造失败：没有日期满足 min_day_samples={min_day_samples}。")\n    return ranked.loc[mask].to_numpy(dtype=np.float32), mask\n\n\ndef _prepare_labels(\n    X: np.ndarray,\n    y: np.ndarray,\n    index_df: pd.DataFrame,\n    *,\n    stage: str,\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, dict[str, Any]]:\n    """根据 LABEL_MODE 生成训练/验证标签。只处理标签，不构造输入特征。"""\n    label_mode = LABEL_MODE.lower()\n    metadata: dict[str, Any] = {f"{stage}_label_mode": label_mode}\n\n    if label_mode in {"daily_rank", "rank", "rank_pct"}:\n        ranked_y, mask = _make_daily_rank_labels(y, index_df, min_day_samples=MIN_RANK_DAY_SAMPLES)\n        X = X[mask]\n        index_df = index_df.iloc[np.flatnonzero(mask)].reset_index(drop=True)\n        y = np.clip(ranked_y, -1.0, 1.0).astype(np.float32)\n        metadata.update(\n            {\n                f"{stage}_label_type": "daily_cross_section_rank_pct_scaled_to_minus1_1",\n                f"{stage}_min_rank_day_samples": MIN_RANK_DAY_SAMPLES,\n            }\n        )\n    elif label_mode in {"raw_return", "return", "mse_return"}:\n        lower, upper = np.percentile(y, [1, 99])\n        y = np.clip(y, lower, upper).astype(np.float32)\n        metadata.update(\n            {\n                f"{stage}_label_type": "next_day_raw_return_winsor_1_99",\n                f"{stage}_winsor_lower": float(lower),\n                f"{stage}_winsor_upper": float(upper),\n            }\n        )\n    else:\n        raise ValueError(f"未知 DIFFMLANET_LABEL_MODE={LABEL_MODE!r}，可选 daily_rank/raw_return。")\n\n    metadata.update(\n        {\n            f"{stage}_sample_count_after_label": int(len(y)),\n            f"{stage}_label_mean": float(np.mean(y)),\n            f"{stage}_label_std": float(np.std(y)),\n            f"{stage}_label_min": float(np.min(y)),\n            f"{stage}_label_max": float(np.max(y)),\n        }\n    )\n    return X.astype(np.float32, copy=False), y.astype(np.float32, copy=False), index_df, metadata\n\n\ndef _build_loss_fn() -> nn.Module:\n    if LOSS_NAME in {"smooth_l1", "huber"}:\n        return nn.SmoothL1Loss(beta=SMOOTH_L1_BETA)\n    if LOSS_NAME in {"mse", "mse_loss"}:\n        return nn.MSELoss()\n    raise ValueError(f"未知 DIFFMLANET_LOSS={LOSS_NAME!r}，可选 smooth_l1/mse。")\n\n\ndef _is_val_date(index_df: pd.DataFrame) -> np.ndarray:\n    if not USE_VALIDATION:\n        return np.zeros(len(index_df), dtype=bool)\n    dates = pd.to_datetime(index_df["date"], errors="coerce").dt.normalize()\n    start = pd.Timestamp(VALID_START).normalize()\n    end = pd.Timestamp(VALID_END).normalize()\n    return ((dates >= start) & (dates <= end)).to_numpy()\n\n\ndef _append_train_val_parts(\n    X_tmp: np.ndarray,\n    y_tmp: np.ndarray,\n    index_tmp: pd.DataFrame,\n    *,\n    X_train_parts: list[np.ndarray],\n    y_train_parts: list[np.ndarray],\n    index_train_parts: list[pd.DataFrame],\n    X_val_parts: list[np.ndarray],\n    y_val_parts: list[np.ndarray],\n    index_val_parts: list[pd.DataFrame],\n) -> None:\n    val_mask = _is_val_date(index_tmp)\n    train_mask = ~val_mask\n    if bool(train_mask.any()):\n        X_train_parts.append(X_tmp[train_mask])\n        y_train_parts.append(y_tmp[train_mask])\n        index_train_parts.append(index_tmp.loc[train_mask].reset_index(drop=True))\n    if bool(val_mask.any()):\n        X_val_parts.append(X_tmp[val_mask])\n        y_val_parts.append(y_tmp[val_mask])\n        index_val_parts.append(index_tmp.loc[val_mask].reset_index(drop=True))\n\n\ndef _concat_or_empty(parts: list[np.ndarray], *, shape_tail: tuple[int, ...], dtype=np.float32) -> np.ndarray:\n    if parts:\n        return np.concatenate(parts).astype(dtype, copy=False)\n    return np.empty((0, *shape_tail), dtype=dtype)\n\n\ndef _concat_index(parts: list[pd.DataFrame]) -> pd.DataFrame:\n    if parts:\n        return pd.concat(parts, ignore_index=True)\n    return pd.DataFrame(columns=["date", "instrument"])\n\n\ndef _compute_stats(X_train: np.ndarray) -> tuple[np.ndarray, np.ndarray]:\n    flat = X_train.reshape(-1, len(FEATURE_COLS))\n    mean = flat.mean(axis=0, dtype=np.float64).astype(np.float32)\n    std = (flat.std(axis=0, dtype=np.float64) + 1e-6).astype(np.float32)\n    std[std < 1e-6] = 1.0\n    return mean, std\n\n\ndef _apply_stats_inplace(X: np.ndarray, stats: tuple[np.ndarray, np.ndarray]) -> np.ndarray:\n    if len(X) == 0:\n        return X.astype(np.float32, copy=False)\n    mean, std = stats\n    X -= mean.reshape(1, 1, -1)\n    X /= std.reshape(1, 1, -1)\n    return X.astype(np.float32, copy=False)\n\n\ndef _finalize_train_val_data(\n    X_train_parts: list[np.ndarray],\n    y_train_parts: list[np.ndarray],\n    index_train_parts: list[pd.DataFrame],\n    X_val_parts: list[np.ndarray],\n    y_val_parts: list[np.ndarray],\n    index_val_parts: list[pd.DataFrame],\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, np.ndarray, np.ndarray, pd.DataFrame, tuple[np.ndarray, np.ndarray]]:\n    if not X_train_parts:\n        raise RuntimeError("训练区间没有构造出任何训练样本；请检查 VALID_START/VALID_END 是否把全部数据都划成验证集。")\n\n    X_train = _concat_or_empty(X_train_parts, shape_tail=(SEQ_LEN, len(FEATURE_COLS)))\n    y_train = _concat_or_empty(y_train_parts, shape_tail=(), dtype=np.float32)\n    index_train = _concat_index(index_train_parts)\n\n    X_val = _concat_or_empty(X_val_parts, shape_tail=(SEQ_LEN, len(FEATURE_COLS)))\n    y_val = _concat_or_empty(y_val_parts, shape_tail=(), dtype=np.float32)\n    index_val = _concat_index(index_val_parts)\n\n    stats = _compute_stats(X_train)\n    X_train = _apply_stats_inplace(X_train, stats)\n    X_val = _apply_stats_inplace(X_val, stats)\n    return X_train, y_train, index_train, X_val, y_val, index_val, stats\n\n\ndef load_training_samples(\n    data_path: str,\n    *,\n    train_start: str,\n    train_end: str,\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, np.ndarray, np.ndarray, pd.DataFrame, tuple[np.ndarray, np.ndarray]]:\n    """读取本地 parquet 并构造训练/验证样本。\n\n    合规说明：这里只使用原始字段窗口，除允许的缺失填充、按字段 log1p、标准化外，\n    不构造跨字段算子、滚动统计、人工因子、降维特征。\n    """\n    files = discover_parquet_files(data_path)\n    if len(files) < 2:\n        raise RuntimeError("训练至少需要两个 parquet 文件，以便计算下一交易日收益标签")\n\n    instruments = _select_local_instruments(files[0])\n    start_ts = pd.Timestamp(train_start).normalize()\n    end_ts = pd.Timestamp(train_end).normalize()\n\n    X_train_parts: list[np.ndarray] = []\n    y_train_parts: list[np.ndarray] = []\n    index_train_parts: list[pd.DataFrame] = []\n    X_val_parts: list[np.ndarray] = []\n    y_val_parts: list[np.ndarray] = []\n    index_val_parts: list[pd.DataFrame] = []\n\n    for file_index, path in enumerate(files):\n        current = to_canonical(pd.read_parquet(path), is_local=True)\n        current_days = current["date"].dt.normalize()\n        sample_start = max(current_days.min(), start_ts)\n        sample_end = min(current_days.max(), end_ts)\n        if sample_start > sample_end:\n            continue\n\n        if file_index + 1 < len(files):\n            next_df = to_canonical(pd.read_parquet(files[file_index + 1]), is_local=True)\n            pair = pd.concat([current, next_df], ignore_index=True)\n        else:\n            pair = current\n\n        pair_end_day = pair["date"].dt.normalize().max()\n        try:\n            X_tmp, y_tmp, index_tmp, _ = build_samples(\n                pair,\n                start_date=f"{sample_start:%Y-%m-%d} 00:00:00",\n                end_date=f"{pair_end_day:%Y-%m-%d} 23:59:59",\n                mode="train",\n                instruments=instruments,\n                normalize=False,\n            )\n        except RuntimeError as exc:\n            log("训练样本跳过", file=f"{file_index + 1}/{len(files)}", reason=str(exc))\n            continue\n\n        index_dates = pd.to_datetime(index_tmp["date"]).dt.normalize()\n        keep = ((index_dates >= sample_start) & (index_dates <= sample_end)).to_numpy()\n        if not bool(keep.any()):\n            continue\n\n        X_tmp = X_tmp[keep]\n        y_tmp = y_tmp[keep]\n        index_tmp = index_tmp.loc[keep].reset_index(drop=True)\n        _append_train_val_parts(\n            X_tmp,\n            y_tmp,\n            index_tmp,\n            X_train_parts=X_train_parts,\n            y_train_parts=y_train_parts,\n            index_train_parts=index_train_parts,\n            X_val_parts=X_val_parts,\n            y_val_parts=y_val_parts,\n            index_val_parts=index_val_parts,\n        )\n        log(\n            "训练样本读取",\n            file=f"{file_index + 1}/{len(files)}",\n            start=str(sample_start.date()),\n            end=str(sample_end.date()),\n            samples=int(keep.sum()),\n        )\n\n    return _finalize_train_val_data(\n        X_train_parts,\n        y_train_parts,\n        index_train_parts,\n        X_val_parts,\n        y_val_parts,\n        index_val_parts,\n    )\n\n\ndef _date_batches(index_df: pd.DataFrame, *, shuffle: bool, seed: int) -> list[np.ndarray]:\n    frame = index_df.copy().reset_index(drop=True)\n    frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.normalize()\n    frame["_row"] = np.arange(len(frame), dtype=np.int64)\n    batches = [group["_row"].to_numpy(dtype=np.int64) for _, group in frame.groupby("date", sort=True)]\n    batches = [batch for batch in batches if len(batch) >= MIN_IC_DAY_SAMPLES]\n    if shuffle:\n        rng = np.random.default_rng(seed)\n        rng.shuffle(batches)\n    return batches\n\n\ndef _negative_corr_loss(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:\n    pred = pred.float().view(-1)\n    target = target.float().view(-1)\n    if pred.numel() < 2:\n        return pred.new_tensor(0.0)\n    pred = pred - pred.mean()\n    target = target - target.mean()\n    denom = torch.sqrt(torch.sum(pred * pred) + 1e-8) * torch.sqrt(torch.sum(target * target) + 1e-8)\n    corr = torch.sum(pred * target) / denom.clamp_min(1e-8)\n    return -corr\n\n\ndef _predict_numpy(model: nn.Module, X: np.ndarray, *, device: torch.device) -> np.ndarray:\n    if len(X) == 0:\n        return np.empty((0,), dtype=np.float64)\n    output: list[np.ndarray] = []\n    model.eval()\n    with torch.inference_mode():\n        for start in range(0, len(X), BATCH):\n            batch = torch.from_numpy(X[start:start + BATCH]).to(device, non_blocking=True)\n            output.append(model(batch).detach().cpu().numpy())\n    return np.concatenate(output).astype(np.float64)\n\n\ndef _rankic_metrics(pred: np.ndarray, y: np.ndarray, index_df: pd.DataFrame) -> dict[str, Any]:\n    if len(pred) == 0 or len(y) == 0:\n        return {"rankic_mean": None, "rankic_std": None, "rankic_ir": None, "rankic_days": 0}\n\n    frame = index_df.copy().reset_index(drop=True)\n    frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.normalize()\n    frame["_pred"] = np.asarray(pred, dtype=np.float64)\n    frame["_y"] = np.asarray(y, dtype=np.float64)\n    frame = frame.replace([np.inf, -np.inf], np.nan).dropna(subset=["date", "_pred", "_y"])\n\n    values: list[float] = []\n    for _, group in frame.groupby("date", sort=True):\n        if len(group) < MIN_IC_DAY_SAMPLES:\n            continue\n        pred_rank = group["_pred"].rank(method="average").to_numpy(dtype=np.float64)\n        true_rank = group["_y"].rank(method="average").to_numpy(dtype=np.float64)\n        pred_rank -= pred_rank.mean()\n        true_rank -= true_rank.mean()\n        denom = np.sqrt(np.sum(pred_rank ** 2)) * np.sqrt(np.sum(true_rank ** 2))\n        if denom > 1e-12:\n            values.append(float(np.sum(pred_rank * true_rank) / denom))\n\n    if not values:\n        return {"rankic_mean": None, "rankic_std": None, "rankic_ir": None, "rankic_days": 0}\n    arr = np.asarray(values, dtype=np.float64)\n    mean = float(arr.mean())\n    std = float(arr.std(ddof=0))\n    return {\n        "rankic_mean": mean,\n        "rankic_std": std,\n        "rankic_ir": float(mean / (std + 1e-12)),\n        "rankic_days": int(len(arr)),\n    }\n\n\ndef _evaluate_rankic(\n    model: nn.Module,\n    X_val: np.ndarray,\n    y_val: np.ndarray,\n    index_val: pd.DataFrame,\n    *,\n    device: torch.device,\n) -> dict[str, Any]:\n    pred = _predict_numpy(model, X_val, device=device)\n    return _rankic_metrics(pred, y_val, index_val)\n\n\ndef _fit_and_save(\n    X_train: np.ndarray,\n    y_train: np.ndarray,\n    index_train: pd.DataFrame,\n    X_val: np.ndarray,\n    y_val: np.ndarray,\n    index_val: pd.DataFrame,\n    stats: tuple[np.ndarray, np.ndarray],\n    *,\n    model_path: str | os.PathLike,\n    metadata: dict[str, Any],\n) -> str:\n    seed_everything(SEED)\n    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")\n    config = model_config()\n\n    X_train, y_train, index_train, train_label_metadata = _prepare_labels(X_train, y_train, index_train, stage="train")\n    val_label_metadata: dict[str, Any] = {}\n    has_validation = USE_VALIDATION and len(X_val) > 0 and len(y_val) > 0\n    if has_validation:\n        X_val, y_val, index_val, val_label_metadata = _prepare_labels(X_val, y_val, index_val, stage="val")\n        has_validation = len(X_val) > 0\n\n    model = build_model(config).to(device)\n    parameter_count = validate_model_size(model)\n    log(\n        "训练数据准备完成",\n        X_shape=str(X_train.shape),\n        y_shape=str(y_train.shape),\n        val_shape=str(X_val.shape) if has_validation else "None",\n        trainable_params=parameter_count,\n        device=str(device),\n        label_mode=LABEL_MODE,\n        loss=LOSS_NAME,\n        ic_alpha=IC_LOSS_ALPHA,\n        y_mean=round(float(np.mean(y_train)), 6),\n        y_std=round(float(np.std(y_train)), 6),\n    )\n\n    train_batches = _date_batches(index_train, shuffle=True, seed=SEED)\n    if not train_batches:\n        raise RuntimeError("按日期 batch 构造失败：没有满足 MIN_IC_DAY_SAMPLES 的训练日期。")\n    log("日期 batch 构造完成", train_days=len(train_batches), min_day_samples=MIN_IC_DAY_SAMPLES)\n\n    optimizer = torch.optim.AdamW(\n        model.parameters(),\n        lr=LR,\n        weight_decay=float(os.environ.get("DIFFMLANET_WEIGHT_DECAY", "0.0005")),\n    )\n    loss_fn = _build_loss_fn()\n\n    best_score = -1e18\n    best_epoch = 0\n    best_state: dict[str, torch.Tensor] | None = None\n    best_metrics: dict[str, Any] = {}\n\n    for epoch in range(EPOCHS):\n        started = time.time()\n        model.train()\n        total_loss = 0.0\n        total_reg = 0.0\n        total_ic = 0.0\n        total_diff = 0.0\n        batches = 0\n        epoch_batches = _date_batches(index_train, shuffle=True, seed=SEED + epoch)\n        for batch_index in epoch_batches:\n            X_batch = torch.from_numpy(X_train[batch_index]).to(device, non_blocking=True)\n            y_batch = torch.from_numpy(y_train[batch_index]).to(device, non_blocking=True)\n            optimizer.zero_grad(set_to_none=True)\n            if config.diffusion_enabled:\n                pred, diffusion_loss = model(X_batch, return_diffusion_loss=True)\n            else:\n                pred = model(X_batch)\n                diffusion_loss = pred.new_tensor(0.0)\n            reg_loss = loss_fn(pred, y_batch)\n            ic_loss = _negative_corr_loss(pred, y_batch)\n            loss = reg_loss + float(config.lambda_diff) * diffusion_loss + IC_LOSS_ALPHA * ic_loss\n            loss.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            optimizer.step()\n\n            total_loss += float(loss.item())\n            total_reg += float(reg_loss.item())\n            total_ic += float(ic_loss.item())\n            total_diff += float(diffusion_loss.item())\n            batches += 1\n\n        epoch_info = {\n            "epoch": epoch + 1,\n            "loss": round(total_loss / max(batches, 1), 8),\n            "reg": round(total_reg / max(batches, 1), 8),\n            "ic_loss": round(total_ic / max(batches, 1), 8),\n            "diff": round(total_diff / max(batches, 1), 8),\n            "elapsed": round(time.time() - started, 2),\n        }\n\n        if has_validation:\n            metrics = _evaluate_rankic(model, X_val, y_val, index_val, device=device)\n            rankic_mean = metrics.get("rankic_mean")\n            epoch_info.update(\n                {\n                    "val_rankic": None if rankic_mean is None else round(float(rankic_mean), 8),\n                    "val_ir": None if metrics.get("rankic_ir") is None else round(float(metrics["rankic_ir"]), 6),\n                    "val_days": metrics.get("rankic_days", 0),\n                }\n            )\n            score = -1e18 if rankic_mean is None else float(rankic_mean)\n            if score > best_score:\n                best_score = score\n                best_epoch = epoch + 1\n                best_metrics = metrics\n                best_state = {key: value.detach().cpu().clone() for key, value in model.state_dict().items()}\n                epoch_info["best"] = True\n        else:\n            best_epoch = epoch + 1\n            best_state = {key: value.detach().cpu().clone() for key, value in model.state_dict().items()}\n            best_score = 0.0\n            best_metrics = {}\n\n        log("epoch 完成", **epoch_info)\n\n    if best_state is not None:\n        model.load_state_dict(best_state)\n\n    metadata = dict(metadata)\n    metadata.update(train_label_metadata)\n    metadata.update(val_label_metadata)\n    metadata.update(\n        {\n            "model_family": "standalone_re_mlanet4_diffusion_rankic_best_v3",\n            "sample_count": int(len(y_train)),\n            "val_sample_count": int(len(y_val)) if has_validation else 0,\n            "trainable_params": int(parameter_count),\n            "loss_name": LOSS_NAME,\n            "smooth_l1_beta": SMOOTH_L1_BETA if LOSS_NAME in {"smooth_l1", "huber"} else None,\n            "ic_loss_alpha": float(IC_LOSS_ALPHA),\n            "min_ic_day_samples": int(MIN_IC_DAY_SAMPLES),\n            "use_validation": bool(has_validation),\n            "valid_start": VALID_START if has_validation else None,\n            "valid_end": VALID_END if has_validation else None,\n            "best_epoch": int(best_epoch),\n            "best_val_rankic_mean": best_metrics.get("rankic_mean"),\n            "best_val_rankic_ir": best_metrics.get("rankic_ir"),\n            "best_val_rankic_days": best_metrics.get("rankic_days"),\n            "score_postprocess": "daily_rank_pct_scaled_to_minus1_1",\n            "input_rule_note": "raw_fields_only; missing_fill_log1p_standardization_allowed; no_handcrafted_factors",\n        }\n    )\n    saved = save_model_json(model, stats=stats, model_path=model_path, config=config, metadata=metadata)\n    log("模型已保存", path=saved, best_epoch=best_epoch, best_val_rankic=best_metrics.get("rankic_mean"))\n    return saved\n\n\ndef train_and_save_local(\n    data_path: str = LOCAL_DATA_PATH,\n    model_path: str | os.PathLike = MODEL_PATH,\n    train_start: str = LOCAL_TRAIN_START,\n    train_end: str = LOCAL_TRAIN_END,\n) -> str:\n    is_smoke_test = (\n        pd.Timestamp(train_start).normalize() > pd.Timestamp(PUBLIC_TRAIN_START).normalize()\n        or pd.Timestamp(train_end).normalize() < pd.Timestamp(PUBLIC_TRAIN_END).normalize()\n        or MAX_LOCAL_INSTRUMENTS > 0\n    )\n    log(\n        "本地训练开始",\n        data_path=data_path,\n        start=train_start,\n        end=train_end,\n        validation=USE_VALIDATION,\n        valid_start=VALID_START if USE_VALIDATION else None,\n        valid_end=VALID_END if USE_VALIDATION else None,\n        smoke_test=is_smoke_test,\n    )\n    X_train, y_train, index_train, X_val, y_val, index_val, stats = load_training_samples(\n        data_path,\n        train_start=train_start,\n        train_end=train_end,\n    )\n    return _fit_and_save(\n        X_train,\n        y_train,\n        index_train,\n        X_val,\n        y_val,\n        index_val,\n        stats,\n        model_path=model_path,\n        metadata={\n            "train_start": train_start,\n            "train_end": train_end,\n            "data_path": str(data_path),\n            "smoke_test": is_smoke_test,\n            "instrument_limit": MAX_LOCAL_INSTRUMENTS,\n        },\n    )\n\n\ndef _require_dai() -> None:\n    if dai is None:\n        raise ModuleNotFoundError("云端训练需要 BigQuant dai 环境")\n\n\ndef _pool(start_date: str, end_date: str) -> list[str]:\n    _require_dai()\n    frame = dai.query(\n        "SELECT DISTINCT instrument FROM bigalpha_2026_instruments",\n        filters={"date": [start_date, end_date]},\n    ).df()\n    instruments = sorted(frame["instrument"].dropna().astype(str).unique().tolist())\n    if MAX_TRAIN_INSTRUMENTS > 0:\n        instruments = instruments[:MAX_TRAIN_INSTRUMENTS]\n    return instruments\n\n\ndef _query_cloud_samples(\n    table: str,\n    train_start: str,\n    train_end: str,\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, np.ndarray, np.ndarray, pd.DataFrame, tuple[np.ndarray, np.ndarray]]:\n    bar_start, bar_end = full_day_bounds(train_start, train_end)\n    instruments = _pool(train_start, train_end)\n    sql = f"SELECT date, instrument, {\', \'.join(FEATURE_COLS)} FROM {table} ORDER BY instrument, date"\n\n    X_train_parts: list[np.ndarray] = []\n    y_train_parts: list[np.ndarray] = []\n    index_train_parts: list[pd.DataFrame] = []\n    X_val_parts: list[np.ndarray] = []\n    y_val_parts: list[np.ndarray] = []\n    index_val_parts: list[pd.DataFrame] = []\n\n    for offset in range(0, len(instruments), TRAIN_CHUNK):\n        chunk = instruments[offset:offset + TRAIN_CHUNK]\n        raw = dai.query(sql, filters={"date": [bar_start, bar_end], "instrument": chunk}).df()\n        if raw.empty:\n            continue\n        canonical = to_canonical(raw, is_local=False)\n        try:\n            X_chunk, y_chunk, index_chunk, _ = build_samples(\n                canonical,\n                start_date=bar_start,\n                end_date=bar_end,\n                mode="train",\n                instruments=chunk,\n                normalize=False,\n            )\n        except RuntimeError as exc:\n            log("云端训练分块跳过", instruments=f"{min(offset + len(chunk), len(instruments))}/{len(instruments)}", reason=str(exc))\n            continue\n        _append_train_val_parts(\n            X_chunk,\n            y_chunk,\n            index_chunk,\n            X_train_parts=X_train_parts,\n            y_train_parts=y_train_parts,\n            index_train_parts=index_train_parts,\n            X_val_parts=X_val_parts,\n            y_val_parts=y_val_parts,\n            index_val_parts=index_val_parts,\n        )\n        log("云端训练数据", instruments=f"{min(offset + len(chunk), len(instruments))}/{len(instruments)}", samples=len(y_chunk))\n\n    return _finalize_train_val_data(\n        X_train_parts,\n        y_train_parts,\n        index_train_parts,\n        X_val_parts,\n        y_val_parts,\n        index_val_parts,\n    )\n\n\ndef train_and_save(\n    datasources: dict,\n    model_path: str | os.PathLike = MODEL_PATH,\n    train_start: str = PUBLIC_TRAIN_START,\n    train_end: str = PUBLIC_TRAIN_END,\n) -> str:\n    _require_dai()\n    table = datasources["bar1m"]\n    X_train, y_train, index_train, X_val, y_val, index_val, stats = _query_cloud_samples(table, train_start, train_end)\n    return _fit_and_save(\n        X_train,\n        y_train,\n        index_train,\n        X_val,\n        y_val,\n        index_val,\n        stats,\n        model_path=model_path,\n        metadata={\n            "train_start": train_start,\n            "train_end": train_end,\n            "table": table,\n            "smoke_test": MAX_TRAIN_INSTRUMENTS > 0,\n            "instrument_limit": MAX_TRAIN_INSTRUMENTS,\n        },\n    )\n\n\ndef _platform_datasources() -> dict | None:\n    g = globals()\n    if "datasources" in g:\n        value = g["datasources"]\n        return {"bar1m": value} if isinstance(value, str) else value\n    if "datasource" in g:\n        return {"bar1m": g["datasource"]} if isinstance(g["datasource"], str) else g["datasource"]\n    return None\n\n\ndef _platform_train_dates() -> tuple[str, str]:\n    g = globals()\n    start_value = g.get("train_start_date", g.get("train_start", PUBLIC_TRAIN_START))\n    end_value = g.get("train_end_date", g.get("train_end", PUBLIC_TRAIN_END))\n    return str(start_value), str(end_value)\n\n\nif __name__ == "__main__":\n    platform_datasources = _platform_datasources()\n    force_local = os.environ.get("DIFFMLANET_USE_LOCAL") == "1"\n    force_cloud = os.environ.get("DIFFMLANET_USE_CLOUD") == "1"\n\n    if force_local or (platform_datasources is None and not force_cloud):\n        if platform_datasources is None and not force_local:\n            log("未检测到平台 datasources，默认使用本地 parquet 训练")\n        model_path = train_and_save_local()\n    else:\n        if platform_datasources is None:\n            platform_datasources = {\n                "bar1m": os.environ.get("DIFFMLANET_CLOUD_BAR1M_TABLE", "bigalpha_2026_stock_bar1m")\n            }\n            log("强制云端训练，使用默认云端训练数据源", datasources=platform_datasources)\n\n        train_start_value, train_end_value = _platform_train_dates()\n        model_path = train_and_save(\n            platform_datasources,\n            model_path=MODEL_PATH,\n            train_start=train_start_value,\n            train_end=train_end_value,\n        )\n    print(model_path)\n'
SOURCE_5M = '# -*- coding: utf-8 -*-\n"""Standalone diff-mLANet style training file for BigAlpha.\n\n这个文件刻意做成单文件自包含：转成 train.ipynb 后，只需要配套\ninfer.ipynb 和 model.json，不再依赖 diff_mlanet_arch.py、layers/ 或项目根目录\n里的其它 Python 文件。\n"""\n\nfrom __future__ import annotations\n\nimport glob\nimport json\nimport math\nimport os\nimport random\nimport time\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom torch.utils.data import DataLoader, TensorDataset\n\ntry:\n    import dai\nexcept ModuleNotFoundError:\n    try:\n        from bigquant import dai\n    except ModuleNotFoundError:\n        dai = None\n\n\nROOT = Path(__file__).resolve().parent if "__file__" in globals() else Path.cwd()\nPROJECT_ROOT = ROOT.parent\nMODEL_PATH = Path(os.environ.get("DIFFMLANET_MODEL_PATH", ROOT / "model.json"))\n\nPUBLIC_TRAIN_START = "2019-01-01"\nPUBLIC_TRAIN_END = "2023-12-31 23:59:59"\n# re-DM3 当前作为官方 5分钟数据实验版。\n# 5m 一天约 48 根 bar，因此默认取当天全部 5m 序列。\nBAR_FREQ = "5m"\nSEQ_LEN = int(os.environ.get("DIFFMLANET_SEQ_LEN", "48"))\nSEED = int(os.environ.get("DIFFMLANET_SEED", "42"))\nEPOCHS = int(os.environ.get("DIFFMLANET_EPOCHS", "5"))\nBATCH = int(os.environ.get("DIFFMLANET_BATCH", "512"))\nLR = float(os.environ.get("DIFFMLANET_LR", "0.001"))\n\nLOCAL_DATA_PATH = os.environ.get(\n    "LOCAL_DATA_PATH",\n    str(PROJECT_ROOT / "local_data/e2e_bar5m_train_2019_2023"),\n)\nLOCAL_TRAIN_START = os.environ.get("LOCAL_TRAIN_START", PUBLIC_TRAIN_START)\nLOCAL_TRAIN_END = os.environ.get("LOCAL_TRAIN_END", PUBLIC_TRAIN_END)\nMAX_LOCAL_INSTRUMENTS = int(os.environ.get("MAX_LOCAL_INSTRUMENTS", "0"))\nTRAIN_CHUNK = int(os.environ.get("DIFFMLANET_TRAIN_CHUNK", "20"))\nMAX_TRAIN_INSTRUMENTS = int(os.environ.get("DIFFMLANET_MAX_TRAIN_INSTRUMENTS", "0"))\n\n# 比赛适配：默认训练每日截面 rank 标签，而不是直接拟合原始收益率。\n# 这样更贴近公榜/私榜中的每日截面排序目标。\nLABEL_MODE = os.environ.get("DIFFMLANET_LABEL_MODE", "daily_rank").lower()\nMIN_RANK_DAY_SAMPLES = int(os.environ.get("DIFFMLANET_MIN_RANK_DAY_SAMPLES", "100"))\nLOSS_NAME = os.environ.get("DIFFMLANET_LOSS", "smooth_l1").lower()\nSMOOTH_L1_BETA = float(os.environ.get("DIFFMLANET_SMOOTH_L1_BETA", "0.02"))\n\n# 比赛合规改进：不引入人工特征分支，只在训练目标和模型选择上优化。\n# 默认用 2023 年做验证集，每轮按验证 RankIC 保存最佳模型。\nUSE_VALIDATION = os.environ.get("DIFFMLANET_USE_VALIDATION", "1") != "0"\nVALID_START = os.environ.get("DIFFMLANET_VALID_START", "2023-01-01")\nVALID_END = os.environ.get("DIFFMLANET_VALID_END", "2023-12-31 23:59:59")\nIC_LOSS_ALPHA = float(os.environ.get("DIFFMLANET_IC_LOSS_ALPHA", "0.05"))\nMIN_IC_DAY_SAMPLES = int(os.environ.get("DIFFMLANET_MIN_IC_DAY_SAMPLES", "100"))\n\n\nOHLC_COLS = ["high", "open", "low", "close"]\nASK_PRICE_COLS = [f"ask_price{i}" for i in range(1, 4)]\nBID_PRICE_COLS = [f"bid_price{i}" for i in range(1, 4)]\nASK_VOLUME_COLS = [f"ask_volume{i}" for i in range(1, 4)]\nBID_VOLUME_COLS = [f"bid_volume{i}" for i in range(1, 4)]\nASK_ORDER_COLS = [f"ask_num_orders{i}" for i in range(1, 4)]\nBID_ORDER_COLS = [f"bid_num_orders{i}" for i in range(1, 4)]\nPRICE_COLS = OHLC_COLS + ASK_PRICE_COLS + BID_PRICE_COLS\nLOG1P_COLS = (\n    ["deal_number", "volume", "amount"]\n    + ASK_VOLUME_COLS\n    + BID_VOLUME_COLS\n    + ASK_ORDER_COLS\n    + BID_ORDER_COLS\n)\nFEATURE_COLS = (\n    ["adjust_factor"]\n    + OHLC_COLS\n    + ["deal_number", "volume", "amount"]\n    + ASK_PRICE_COLS\n    + BID_PRICE_COLS\n    + ASK_VOLUME_COLS\n    + BID_VOLUME_COLS\n    + ASK_ORDER_COLS\n    + BID_ORDER_COLS\n)\nFEATURE_SCHEMA_VERSION = "e2e_bar5m_full_3level_v1"\n\n\ndef log(message: str, **kwargs: Any) -> None:\n    extra = " ".join(f"{key}={value}" for key, value in kwargs.items())\n    print(f"[diffMLANet][train] {message}" + (f" {extra}" if extra else ""))\n\n\ndef seed_everything(seed: int = SEED) -> None:\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed_all(seed)\n\n\ndef full_day_bounds(start_date: str, end_date: str) -> tuple[str, str]:\n    start = pd.Timestamp(start_date).normalize()\n    end = pd.Timestamp(end_date).normalize() + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)\n    return start.strftime("%Y-%m-%d %H:%M:%S"), end.strftime("%Y-%m-%d %H:%M:%S")\n\n\ndef to_canonical(df: pd.DataFrame, *, is_local: bool) -> pd.DataFrame:\n    df = df.copy()\n    df["date"] = pd.to_datetime(df["date"])\n    if is_local:\n        # 本地 parquet 中价格类字段可能用 -1 表示缺失。\n        # 需要先把所有价格字段的 -1 置空，再做 /100 缩放，避免 -1 被错误变成 -0.01。\n        for col in PRICE_COLS:\n            if col in df.columns:\n                df.loc[df[col] == -1, col] = np.nan\n        for col in PRICE_COLS + ["amount"]:\n            if col in df.columns:\n                df[col] = df[col].astype("float64") / 100.0\n        if "instrument" not in df.columns:\n            df["instrument"] = df["instrument_id"].astype(str)\n    else:\n        df["instrument"] = df["instrument"].astype(str)\n\n    missing = [col for col in FEATURE_COLS if col not in df.columns]\n    if missing:\n        raise ValueError(f"输入数据缺少模型字段: {missing}")\n    return (\n        df[["date", "instrument"] + FEATURE_COLS]\n        .dropna(subset=["date", "instrument"])\n        .sort_values(["instrument", "date"])\n        .reset_index(drop=True)\n    )\n\n\ndef _prepare_one_day(day_df: pd.DataFrame) -> tuple[np.ndarray, float] | None:\n    day_df = day_df.sort_values("date")\n    if len(day_df) < SEQ_LEN:\n        return None\n    feature_df = day_df[FEATURE_COLS].copy()\n    for col in LOG1P_COLS:\n        feature_df[col] = np.log1p(pd.to_numeric(feature_df[col], errors="coerce").clip(lower=0))\n    feature_df = feature_df.replace([np.inf, -np.inf], np.nan).ffill().fillna(0.0)\n    window = feature_df.iloc[-SEQ_LEN:].to_numpy(dtype=np.float32)\n    close = pd.to_numeric(day_df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()\n    close_value = float(close.iloc[-1]) if len(close) else np.nan\n    return window, close_value\n\n\ndef build_samples(\n    df: pd.DataFrame,\n    *,\n    start_date: str,\n    end_date: str,\n    mode: str,\n    instruments: list[str] | None = None,\n    stats: tuple[np.ndarray, np.ndarray] | None = None,\n    normalize: bool = True,\n) -> tuple[np.ndarray, np.ndarray | None, pd.DataFrame, tuple[np.ndarray, np.ndarray] | None]:\n    start_ts = pd.Timestamp(start_date)\n    end_ts = pd.Timestamp(end_date)\n    data = df[(df["date"] >= start_ts) & (df["date"] <= end_ts)].copy()\n    if instruments is not None:\n        wanted = {str(item) for item in instruments}\n        data = data[data["instrument"].astype(str).isin(wanted)]\n    if data.empty:\n        raise RuntimeError(f"指定区间没有数据: {start_date} ~ {end_date}")\n\n    windows: list[np.ndarray] = []\n    labels: list[np.float32] = []\n    keys: list[tuple[pd.Timestamp, str]] = []\n    for instrument, instrument_df in data.groupby("instrument", sort=False):\n        daily: list[tuple[pd.Timestamp, np.ndarray, float]] = []\n        for day, day_df in instrument_df.groupby(instrument_df["date"].dt.normalize(), sort=True):\n            prepared = _prepare_one_day(day_df)\n            if prepared is not None:\n                window, close = prepared\n                daily.append((pd.Timestamp(day), window, close))\n        for index, (day, window, close) in enumerate(daily):\n            label = None\n            if index + 1 < len(daily):\n                next_close = daily[index + 1][2]\n                if np.isfinite(close) and np.isfinite(next_close) and close > 0:\n                    value = next_close / close - 1.0\n                    if np.isfinite(value):\n                        label = np.float32(value)\n            if mode == "train" and label is None:\n                continue\n            windows.append(window)\n            keys.append((day, str(instrument)))\n            if mode == "train":\n                labels.append(label)\n\n    if not windows:\n        raise RuntimeError(f"没有构造出样本: mode={mode}, {start_date} ~ {end_date}")\n    X = np.stack(windows).astype(np.float32)\n    if stats is None and mode == "train":\n        flat = X.reshape(-1, len(FEATURE_COLS))\n        stats = (\n            flat.mean(axis=0, dtype=np.float64).astype(np.float32),\n            (flat.std(axis=0, dtype=np.float64) + 1e-6).astype(np.float32),\n        )\n    if normalize:\n        if stats is None:\n            raise ValueError("推理或标准化时必须提供训练集 stats")\n        mean, std = stats\n        X = ((X - mean) / std).astype(np.float32)\n    index_df = pd.DataFrame(keys, columns=["date", "instrument"])\n    y = np.asarray(labels, dtype=np.float32) if mode == "train" else None\n    return X, y, index_df, stats\n\n\n\n@dataclass\nclass DiffMLANetConfig:\n    n_feat: int = 26\n    seq_len: int = 64\n    d_model: int = 128\n    conv_windows: list[int] = field(default_factory=lambda: [4, 8, 16, 32, 64])\n    conv_channels: int = 96\n    dropout: float = 0.2\n    aeccm_inplanes: int = 8\n    aeccm_ratio: float = 0.5\n    aeccm_low_rank_ratio: float = 0.25\n    diffusion_enabled: bool = True\n    diffusion_steps: int = 128\n    diffusion_beta_start: float = 1e-4\n    diffusion_beta_end: float = 0.02\n    diffusion_hidden_dim: int = 64\n    diffusion_time_dim: int = 64\n    diffusion_num_blocks: int = 2\n    diffusion_inference_step: int = 64\n    diffusion_denoise_eta: float = 0.2\n    lambda_diff: float = 0.01\n\n\nclass RevIN(nn.Module):\n    def __init__(self, num_variates: int, eps: float = 1e-5):\n        super().__init__()\n        self.eps = eps\n        self.gamma = nn.Parameter(torch.ones(1, num_variates, 1))\n        self.beta = nn.Parameter(torch.zeros(1, num_variates, 1))\n\n    def forward(self, x: torch.Tensor):\n        x_feature = x.permute(0, 2, 1)\n        mean = x_feature.mean(dim=-1, keepdim=True)\n        var = x_feature.var(dim=-1, unbiased=False, keepdim=True)\n        normalized = (x_feature - mean) * var.clamp(min=self.eps).rsqrt()\n        scaled = normalized * self.gamma + self.beta\n        return scaled.permute(0, 2, 1)\n\n\nclass SinusoidalTimeEmbedding(nn.Module):\n    """re-mLANet4 diffusion time embedding, inlined for two-file submission."""\n\n    def __init__(self, dim: int):\n        super().__init__()\n        self.dim = dim\n\n    def forward(self, timesteps: torch.Tensor) -> torch.Tensor:\n        device = timesteps.device\n        half_dim = self.dim // 2\n        if half_dim == 0:\n            return timesteps.float().unsqueeze(-1)\n        scale = math.log(10000) / max(half_dim - 1, 1)\n        freqs = torch.exp(torch.arange(half_dim, device=device) * -scale)\n        args = timesteps.float().unsqueeze(1) * freqs.unsqueeze(0)\n        emb = torch.cat([args.sin(), args.cos()], dim=1)\n        if self.dim % 2 == 1:\n            emb = F.pad(emb, (0, 1))\n        return emb\n\n\ndef _group_count(channels: int, max_groups: int = 8) -> int:\n    for groups in range(min(max_groups, channels), 0, -1):\n        if channels % groups == 0:\n            return groups\n    return 1\n\n\nclass ResidualConvBlock(nn.Module):\n    """Residual 1D conv block used by the re-mLANet4 diffusion denoiser."""\n\n    def __init__(self, channels: int, time_dim: int, dilation: int = 1):\n        super().__init__()\n        padding = dilation\n        groups = _group_count(channels)\n        self.norm1 = nn.GroupNorm(groups, channels)\n        self.conv1 = nn.Conv1d(channels, channels, kernel_size=3, padding=padding, dilation=dilation)\n        self.time_proj = nn.Linear(time_dim, channels)\n        self.norm2 = nn.GroupNorm(groups, channels)\n        self.conv2 = nn.Conv1d(channels, channels, kernel_size=3, padding=padding, dilation=dilation)\n        self.act = nn.SiLU()\n\n    def forward(self, x: torch.Tensor, time_emb: torch.Tensor) -> torch.Tensor:\n        residual = x\n        x = self.conv1(self.act(self.norm1(x)))\n        x = x + self.time_proj(time_emb).unsqueeze(-1)\n        x = self.conv2(self.act(self.norm2(x)))\n        return x + residual\n\n\nclass DiffusionDenoiser(nn.Module):\n    """Lightweight DDPM noise predictor copied from re-mLANet4 and kept self-contained."""\n\n    def __init__(\n        self,\n        seq_len: int,\n        enc_in: int,\n        num_steps: int = 128,\n        beta_start: float = 1e-4,\n        beta_end: float = 0.02,\n        hidden_dim: int = 64,\n        time_dim: int = 64,\n        num_blocks: int = 2,\n        inference_step: int | None = None,\n    ):\n        super().__init__()\n        self.seq_len = seq_len\n        self.enc_in = enc_in\n        self.num_steps = num_steps\n        self.inference_step = num_steps // 2 if inference_step is None else inference_step\n\n        betas = torch.linspace(beta_start, beta_end, num_steps, dtype=torch.float32)\n        alphas = 1.0 - betas\n        alpha_bars = torch.cumprod(alphas, dim=0)\n        self.register_buffer("betas", betas, persistent=False)\n        self.register_buffer("alphas", alphas, persistent=False)\n        self.register_buffer("alpha_bars", alpha_bars, persistent=False)\n\n        self.time_mlp = nn.Sequential(\n            SinusoidalTimeEmbedding(time_dim),\n            nn.Linear(time_dim, time_dim),\n            nn.SiLU(),\n            nn.Linear(time_dim, time_dim),\n        )\n        self.input_proj = nn.Conv1d(1, hidden_dim, kernel_size=3, padding=1)\n        self.blocks = nn.ModuleList(\n            [ResidualConvBlock(hidden_dim, time_dim, dilation=2 ** (idx % 3)) for idx in range(num_blocks)]\n        )\n        self.output_norm = nn.GroupNorm(_group_count(hidden_dim), hidden_dim)\n        self.output_proj = nn.Conv1d(hidden_dim, 1, kernel_size=3, padding=1)\n        self.act = nn.SiLU()\n\n    def _extract(self, values: torch.Tensor, timesteps: torch.Tensor, x: torch.Tensor) -> torch.Tensor:\n        gathered = values.gather(0, timesteps).to(device=x.device, dtype=x.dtype)\n        return gathered.view(-1, 1, 1)\n\n    def _expand_timesteps(self, timesteps: torch.Tensor, channels: int) -> torch.Tensor:\n        return timesteps.unsqueeze(1).expand(-1, channels).reshape(-1)\n\n    def q_sample(\n        self,\n        x0: torch.Tensor,\n        timesteps: torch.Tensor,\n        noise: torch.Tensor | None = None,\n    ) -> tuple[torch.Tensor, torch.Tensor]:\n        if noise is None:\n            noise = torch.randn_like(x0)\n        sqrt_alpha_bar = self._extract(self.alpha_bars.sqrt(), timesteps, x0)\n        sqrt_one_minus_alpha_bar = self._extract((1.0 - self.alpha_bars).sqrt(), timesteps, x0)\n        return sqrt_alpha_bar * x0 + sqrt_one_minus_alpha_bar * noise, noise\n\n    def predict_noise(self, x_t: torch.Tensor, timesteps: torch.Tensor) -> torch.Tensor:\n        batch, length, channels = x_t.shape\n        x = x_t.permute(0, 2, 1).reshape(batch * channels, 1, length)\n        time_emb = self.time_mlp(self._expand_timesteps(timesteps, channels))\n\n        x = self.input_proj(x)\n        for block in self.blocks:\n            x = block(x, time_emb)\n        x = self.output_proj(self.act(self.output_norm(x)))\n        return x.reshape(batch, channels, length).permute(0, 2, 1)\n\n    def predict_clean_from_noise(\n        self,\n        x_t: torch.Tensor,\n        timesteps: torch.Tensor,\n        pred_noise: torch.Tensor,\n    ) -> torch.Tensor:\n        sqrt_alpha_bar = self._extract(self.alpha_bars.sqrt(), timesteps, x_t)\n        sqrt_one_minus_alpha_bar = self._extract((1.0 - self.alpha_bars).sqrt(), timesteps, x_t)\n        return (x_t - sqrt_one_minus_alpha_bar * pred_noise) / sqrt_alpha_bar.clamp(min=1e-8)\n\n    def training_loss(\n        self,\n        x0: torch.Tensor,\n        timesteps: torch.Tensor | None = None,\n        noise: torch.Tensor | None = None,\n    ) -> dict[str, torch.Tensor]:\n        batch = x0.shape[0]\n        if timesteps is None:\n            timesteps = torch.randint(0, self.num_steps, (batch,), device=x0.device)\n        x_t, noise = self.q_sample(x0, timesteps, noise)\n        pred_noise = self.predict_noise(x_t, timesteps)\n        loss = F.mse_loss(pred_noise, noise)\n        x_clean = self.predict_clean_from_noise(x_t, timesteps, pred_noise)\n        return {\n            "loss": loss,\n            "x_clean": x_clean,\n            "x_t": x_t,\n            "pred_noise": pred_noise,\n            "noise": noise,\n            "timesteps": timesteps,\n        }\n\n    def denoise(self, x_t: torch.Tensor, timesteps: torch.Tensor | None = None) -> torch.Tensor:\n        batch = x_t.shape[0]\n        if timesteps is None:\n            step = max(0, min(int(self.inference_step), self.num_steps - 1))\n            timesteps = torch.full((batch,), step, device=x_t.device, dtype=torch.long)\n        pred_noise = self.predict_noise(x_t, timesteps)\n        return self.predict_clean_from_noise(x_t, timesteps, pred_noise)\n\n    def forward(\n        self,\n        x: torch.Tensor,\n        return_loss: bool = False,\n        timesteps: torch.Tensor | None = None,\n    ) -> torch.Tensor | tuple[torch.Tensor, torch.Tensor]:\n        if return_loss:\n            diffusion = self.training_loss(x, timesteps=timesteps)\n            return diffusion["x_clean"], diffusion["loss"]\n        return self.denoise(x, timesteps=timesteps)\n\n\ndef split_window_chains(windows: list[int]) -> list[list[int]]:\n    """Same divisibility-chain idea as re-mLANet4/layers/PyramidalRNNEmbedding.py."""\n    windows = sorted(int(item) for item in windows)\n    used = np.zeros(len(windows), dtype=np.int8)\n    chains: list[list[int]] = []\n    while used.sum() < len(windows):\n        chain = []\n        last = None\n        for index in range(len(windows) - 1, -1, -1):\n            value = windows[index]\n            if used[index] == 0 or index == 0:\n                if last is None:\n                    chain.append(value)\n                    used[index] = 1\n                    last = value\n                elif last % value == 0:\n                    chain.append(value)\n                    used[index] = 1\n                    last = value\n        if chain:\n            chains.append(sorted(chain))\n    return chains\n\n\ndef count_chain_windows(chains: list[list[int]]) -> int:\n    return sum(len(chain) for chain in chains)\n\n\nclass ConvRNNBlock(nn.Module):\n    def __init__(self, kernel: int, conv_channels: int, hidden_size: int):\n        super().__init__()\n        self.conv = nn.Conv1d(1 if kernel == 0 else conv_channels, conv_channels, kernel_size=max(1, kernel), stride=max(1, kernel))\n        self.gru = nn.GRU(conv_channels, hidden_size, batch_first=True)\n\n    def forward_conv(self, x: torch.Tensor) -> torch.Tensor:\n        return self.conv(x)\n\n    def forward_rnn(self, x: torch.Tensor) -> torch.Tensor:\n        _, hidden = self.gru(x.permute(0, 2, 1))\n        return hidden[-1]\n\n\nclass PyramidalRNNEmbedding(nn.Module):\n    """re-mLANet4 PRE: pyramidal convolution chains with GRU summaries."""\n\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        self.config = config\n        self.chains = split_window_chains(config.conv_windows)\n        window_count = count_chain_windows(self.chains)\n        self.rate = nn.Parameter(torch.ones(window_count, 1) / max(window_count, 1))\n        self.temperature = 0.002\n\n        counts = {window: 0 for window in config.conv_windows}\n        for chain in self.chains:\n            for window in chain:\n                counts[window] += 1\n        base_hidden = max(1, config.d_model // len(config.conv_windows))\n        self.hidden_by_window = {\n            window: max(1, base_hidden // max(counts[window], 1))\n            for window in config.conv_windows\n        }\n        out_dim = sum(self.hidden_by_window[window] for chain in self.chains for window in chain)\n\n        modules = []\n        for chain in self.chains:\n            chain_blocks = []\n            previous_window = 1\n            for position, window in enumerate(chain):\n                kernel = int(window / previous_window)\n                hidden = self.hidden_by_window[window]\n                block = nn.ModuleDict(\n                    {\n                        "conv": nn.Conv1d(\n                            1 if position == 0 else config.conv_channels,\n                            config.conv_channels,\n                            kernel_size=max(1, kernel),\n                            stride=max(1, kernel),\n                        ),\n                        "gru": nn.GRU(config.conv_channels, hidden, batch_first=True),\n                    }\n                )\n                chain_blocks.append(block)\n                previous_window = window\n            modules.append(nn.ModuleList(chain_blocks))\n        self.chain_modules = nn.ModuleList(modules)\n        self.out = nn.Linear(out_dim, config.d_model)\n        self.dropout = nn.Dropout(config.dropout)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        batch, seq_len, n_feat = x.shape\n        x = x.permute(0, 2, 1).reshape(batch * n_feat, 1, seq_len)\n        summaries = []\n        rate = torch.softmax((self.rate / self.temperature).squeeze(-1), dim=0)\n        rate = rate * rate.numel()\n        rate_index = 0\n\n        for chain, module_list in zip(self.chains, self.chain_modules):\n            conv_map = {}\n            tmp = x\n            for window, block in zip(chain, module_list):\n                tmp = block["conv"](tmp)\n                conv_map[window] = tmp\n\n            last_window = None\n            upscaled = tmp\n            for window, block in reversed(list(zip(chain, module_list))):\n                if last_window is not None:\n                    scale_factor = last_window / window\n                    upscaled = nn.functional.interpolate(upscaled, scale_factor=scale_factor)\n                    diff = upscaled.shape[-1] - conv_map[window].shape[-1]\n                    if diff < 0:\n                        upscaled = nn.functional.pad(upscaled, (0, -diff), mode="replicate")\n                    elif diff > 0:\n                        upscaled = upscaled[:, :, :-diff]\n                    rnn_input = upscaled + conv_map[window]\n                else:\n                    rnn_input = upscaled\n                hidden, _ = block["gru"](rnn_input.permute(0, 2, 1))\n                summary = hidden[:, -1, :].reshape(batch, n_feat, -1)\n                summaries.append(summary * rate[rate_index])\n                rate_index += 1\n                last_window = window\n\n        tokens = torch.cat(summaries, dim=-1)\n        return self.dropout(self.out(tokens))\n\n\nclass AECCM(nn.Module):\n    """re-mLANet4 AECCM: dense context update + low-rank update + fusion gate."""\n\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        if config.d_model % config.aeccm_inplanes != 0:\n            raise ValueError("d_model must be divisible by aeccm_inplanes")\n        self.d_model = config.d_model\n        self.inplanes = config.aeccm_inplanes\n        planes = max(1, int(self.inplanes * config.aeccm_ratio))\n        rank = max(1, int(self.inplanes * config.aeccm_low_rank_ratio))\n        self.conv_mask = nn.Conv2d(self.inplanes, 1, kernel_size=1)\n        self.softmax = nn.Softmax(dim=2)\n        self.channel_add_conv1 = nn.Sequential(\n            nn.Conv2d(self.inplanes, planes, kernel_size=1),\n            nn.LayerNorm([planes, 1, 1]),\n            nn.ReLU(inplace=True),\n            nn.Conv2d(planes, self.inplanes, kernel_size=1),\n        )\n        self.channel_add_conv2 = nn.Sequential(\n            nn.Conv2d(self.inplanes, planes, kernel_size=3, padding=1),\n            nn.LayerNorm([planes, 1, 1]),\n            nn.ReLU(inplace=True),\n            nn.Conv2d(planes, self.inplanes, kernel_size=3, padding=1),\n        )\n        self.low_rank_down = nn.Conv2d(self.inplanes, rank, kernel_size=1, bias=False)\n        self.low_rank_norm = nn.LayerNorm([rank, 1, 1])\n        self.low_rank_mid = nn.Sequential(\n            nn.Conv2d(rank, rank, kernel_size=3, padding=1, groups=rank, bias=False),\n            nn.ReLU(inplace=True),\n            nn.Conv2d(rank, rank, kernel_size=1, bias=False),\n            nn.ReLU(inplace=True),\n        )\n        self.low_rank_up = nn.Conv2d(rank, self.inplanes, kernel_size=1, bias=False)\n        self.fusion_gate = nn.Sequential(nn.Conv2d(self.inplanes * 2, self.inplanes, kernel_size=1), nn.Sigmoid())\n        self.conv1 = nn.Conv2d(self.inplanes, self.inplanes, kernel_size=1)\n\n    def spatial_attention(self, x: torch.Tensor) -> torch.Tensor:\n        batch, channel, tokens, width = x.size()\n        input_x = x.view(batch, channel, tokens * width).unsqueeze(1)\n        context_mask = self.conv_mask(x).view(batch, 1, tokens * width)\n        context_mask = self.softmax(context_mask).unsqueeze(-1)\n        context = torch.matmul(input_x, context_mask)\n        return context.view(batch, channel, 1, 1)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        batch, tokens, _ = x.shape\n        y = x.reshape(batch, self.inplanes, tokens, self.d_model // self.inplanes)\n        spatial_out = self.spatial_attention(y)\n        dense_out = self.conv1(self.channel_add_conv2(spatial_out) + self.channel_add_conv1(spatial_out))\n        low_rank = self.low_rank_up(self.low_rank_mid(self.low_rank_norm(self.low_rank_down(spatial_out))))\n        gate = self.fusion_gate(torch.cat([dense_out, low_rank], dim=1))\n        out = y + dense_out + gate * low_rank\n        return out.reshape(batch, tokens, self.d_model)\n\n\nclass DiffTokenMixer(nn.Module):\n    """Self-contained gated recurrent mixer used instead of external mLSTM files."""\n\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        self.norm = nn.LayerNorm(config.d_model)\n        self.gru = nn.GRU(\n            input_size=config.d_model,\n            hidden_size=config.d_model // 2,\n            batch_first=True,\n            bidirectional=True,\n        )\n        self.gate = nn.Sequential(nn.Linear(config.d_model, config.d_model), nn.Sigmoid())\n        self.ffn = nn.Sequential(\n            nn.Linear(config.d_model, config.d_model * 2),\n            nn.GELU(),\n            nn.Dropout(config.dropout),\n            nn.Linear(config.d_model * 2, config.d_model),\n        )\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        mixed, _ = self.gru(self.norm(x))\n        mixed = mixed * self.gate(x)\n        return x + mixed + self.ffn(mixed)\n\n\nclass DiffMLANetFactorModel(nn.Module):\n    def __init__(self, config: DiffMLANetConfig):\n        super().__init__()\n        self.config = config\n        self.revin = RevIN(config.n_feat)\n        self.diffusion_enabled = bool(config.diffusion_enabled)\n        self.diffusion_denoise_eta = float(config.diffusion_denoise_eta)\n        self.diffusion_denoiser = None\n        if self.diffusion_enabled:\n            self.diffusion_denoiser = DiffusionDenoiser(\n                seq_len=config.seq_len,\n                enc_in=config.n_feat,\n                num_steps=config.diffusion_steps,\n                beta_start=config.diffusion_beta_start,\n                beta_end=config.diffusion_beta_end,\n                hidden_dim=config.diffusion_hidden_dim,\n                time_dim=config.diffusion_time_dim,\n                num_blocks=config.diffusion_num_blocks,\n                inference_step=config.diffusion_inference_step,\n            )\n        self.embedding = PyramidalRNNEmbedding(config)\n        self.aeccm = AECCM(config)\n        self.mixer1 = DiffTokenMixer(config)\n        self.mixer2 = DiffTokenMixer(config)\n        self.norm = nn.LayerNorm(config.d_model)\n        self.projector = nn.Linear(config.d_model, 1)\n        self.factor_head = nn.Sequential(\n            nn.LayerNorm(config.n_feat * 3),\n            nn.Linear(config.n_feat * 3, config.n_feat * 2),\n            nn.GELU(),\n            nn.Dropout(config.dropout),\n            nn.Linear(config.n_feat * 2, 1),\n        )\n\n    def _apply_diffusion_denoise(self, x: torch.Tensor) -> torch.Tensor:\n        if self.diffusion_denoiser is None:\n            return x\n        x_clean = self.diffusion_denoiser(x)\n        eta = max(0.0, min(float(self.diffusion_denoise_eta), 1.0))\n        return x + eta * (x_clean - x)\n\n    def forward(\n        self,\n        x: torch.Tensor,\n        return_diffusion_loss: bool = False,\n    ) -> torch.Tensor | tuple[torch.Tensor, torch.Tensor]:\n        last_features = x[:, -1, :]\n        normalized = self.revin(x)\n        diffusion_loss = normalized.new_tensor(0.0)\n        if self.diffusion_enabled and self.diffusion_denoiser is not None:\n            if return_diffusion_loss:\n                diffusion_loss = self.diffusion_denoiser.training_loss(normalized)["loss"]\n            normalized = self._apply_diffusion_denoise(normalized)\n        tokens = self.embedding(normalized)\n        tokens = self.aeccm(tokens)\n        tokens = self.mixer2(self.mixer1(tokens))\n        predicted_features = self.projector(self.norm(tokens)).squeeze(-1)\n        diff_features = predicted_features - last_features\n        factor_input = torch.cat([predicted_features, last_features, diff_features], dim=-1)\n        score = self.factor_head(factor_input).squeeze(-1)\n        if return_diffusion_loss:\n            return score, diffusion_loss\n        return score\n\n\ndef model_config() -> DiffMLANetConfig:\n    return DiffMLANetConfig(\n        n_feat=len(FEATURE_COLS),\n        seq_len=SEQ_LEN,\n        d_model=int(os.environ.get("DIFFMLANET_D_MODEL", "128")),\n        conv_windows=[\n            int(item)\n            for item in os.environ.get("DIFFMLANET_CONV_WINDOWS", "3,6,12,24,48").split(",")\n            if item.strip()\n        ],\n        conv_channels=int(os.environ.get("DIFFMLANET_CONV_CHANNELS", "96")),\n        dropout=float(os.environ.get("DIFFMLANET_DROPOUT", "0.2")),\n        diffusion_enabled=os.environ.get("DIFFMLANET_DIFFUSION_ENABLED", "1") != "0",\n        diffusion_steps=int(os.environ.get("DIFFMLANET_DIFFUSION_STEPS", "128")),\n        diffusion_beta_start=float(os.environ.get("DIFFMLANET_DIFFUSION_BETA_START", "0.0001")),\n        diffusion_beta_end=float(os.environ.get("DIFFMLANET_DIFFUSION_BETA_END", "0.02")),\n        diffusion_hidden_dim=int(os.environ.get("DIFFMLANET_DIFFUSION_HIDDEN_DIM", "64")),\n        diffusion_time_dim=int(os.environ.get("DIFFMLANET_DIFFUSION_TIME_DIM", "64")),\n        diffusion_num_blocks=int(os.environ.get("DIFFMLANET_DIFFUSION_NUM_BLOCKS", "2")),\n        diffusion_inference_step=int(os.environ.get("DIFFMLANET_DIFFUSION_INFERENCE_STEP", "64")),\n        diffusion_denoise_eta=float(os.environ.get("DIFFMLANET_DIFFUSION_DENOISE_ETA", "0.2")),\n        lambda_diff=float(os.environ.get("DIFFMLANET_LAMBDA_DIFF", "0.01")),\n    )\n\n\ndef build_model(config: DiffMLANetConfig | dict[str, Any] | None = None) -> DiffMLANetFactorModel:\n    if isinstance(config, dict):\n        base = DiffMLANetConfig()\n        for key, value in config.items():\n            if hasattr(base, key):\n                setattr(base, key, value)\n        config = base\n    elif config is None:\n        config = model_config()\n    return DiffMLANetFactorModel(config)\n\ndef count_trainable_params(model: nn.Module) -> int:\n    return sum(param.numel() for param in model.parameters() if param.requires_grad)\n\n\ndef validate_model_size(model: nn.Module) -> int:\n    count = count_trainable_params(model)\n    if not 100_000 <= count <= 100_000_000:\n        raise RuntimeError(f"模型可训练参数 {count} 不在比赛约束 [100000, 100000000] 内")\n    return count\n\n\ndef save_model_json(\n    model: nn.Module,\n    *,\n    stats: tuple[np.ndarray, np.ndarray],\n    model_path: str | os.PathLike,\n    config: DiffMLANetConfig,\n    metadata: dict[str, Any],\n) -> str:\n    path = Path(model_path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    mean, std = stats\n    payload = {\n        "model_name": "standalone_re_mlanet4_diffusion_factor",\n        "model_cfg": asdict(config),\n        "feature_cols": list(FEATURE_COLS),\n        "feature_schema_version": FEATURE_SCHEMA_VERSION,\n        "stats": {\n            "mean": np.asarray(mean, dtype=np.float32).tolist(),\n            "std": np.asarray(std, dtype=np.float32).tolist(),\n        },\n        "state_dict": {\n            key: value.detach().cpu().numpy().tolist()\n            for key, value in model.state_dict().items()\n        },\n        "metadata": metadata,\n    }\n    path.write_text(json.dumps(payload), encoding="utf-8")\n    return str(path)\n\n\ndef discover_parquet_files(data_path: str) -> list[str]:\n    path = Path(data_path)\n    if path.is_dir():\n        files = sorted((str(item) for item in path.rglob("*.parquet")), key=lambda item: Path(item).name)\n    elif any(char in data_path for char in "*?["):\n        files = sorted(glob.glob(data_path, recursive=True), key=lambda item: Path(item).name)\n    elif path.is_file():\n        files = [str(path)]\n    else:\n        raise FileNotFoundError(f"训练数据路径不存在: {data_path}")\n    if not files:\n        raise FileNotFoundError(f"没有找到 parquet 文件: {data_path}")\n    return files\n\n\ndef _select_local_instruments(first_file: str) -> list[str] | None:\n    if MAX_LOCAL_INSTRUMENTS <= 0:\n        return None\n    first = to_canonical(pd.read_parquet(first_file), is_local=True)\n    instruments = sorted(first["instrument"].dropna().astype(str).unique().tolist())\n    return instruments[:MAX_LOCAL_INSTRUMENTS]\n\n\n\n\ndef _make_daily_rank_labels(\n    y: np.ndarray,\n    index_df: pd.DataFrame,\n    *,\n    min_day_samples: int = MIN_RANK_DAY_SAMPLES,\n) -> tuple[np.ndarray, np.ndarray]:\n    """把原始未来收益转成每日截面 rank 标签。"""\n    frame = index_df.copy().reset_index(drop=True)\n    frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.normalize()\n    frame["_y"] = np.asarray(y, dtype=np.float32)\n    frame["_finite"] = np.isfinite(frame["_y"].to_numpy())\n\n    valid_count = frame.groupby("date")["_finite"].transform("sum")\n    valid = frame["_finite"] & frame["date"].notna() & (valid_count >= int(min_day_samples))\n\n    ranked = pd.Series(np.nan, index=frame.index, dtype="float64")\n    ranked.loc[valid] = frame.loc[valid].groupby("date")["_y"].rank(method="average", pct=True)\n    ranked = (ranked - 0.5) * 2.0\n\n    mask = ranked.notna().to_numpy()\n    if not bool(mask.any()):\n        raise RuntimeError(f"每日 rank 标签构造失败：没有日期满足 min_day_samples={min_day_samples}。")\n    return ranked.loc[mask].to_numpy(dtype=np.float32), mask\n\n\ndef _prepare_labels(\n    X: np.ndarray,\n    y: np.ndarray,\n    index_df: pd.DataFrame,\n    *,\n    stage: str,\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, dict[str, Any]]:\n    """根据 LABEL_MODE 生成训练/验证标签。只处理标签，不构造输入特征。"""\n    label_mode = LABEL_MODE.lower()\n    metadata: dict[str, Any] = {f"{stage}_label_mode": label_mode}\n\n    if label_mode in {"daily_rank", "rank", "rank_pct"}:\n        ranked_y, mask = _make_daily_rank_labels(y, index_df, min_day_samples=MIN_RANK_DAY_SAMPLES)\n        X = X[mask]\n        index_df = index_df.iloc[np.flatnonzero(mask)].reset_index(drop=True)\n        y = np.clip(ranked_y, -1.0, 1.0).astype(np.float32)\n        metadata.update(\n            {\n                f"{stage}_label_type": "daily_cross_section_rank_pct_scaled_to_minus1_1",\n                f"{stage}_min_rank_day_samples": MIN_RANK_DAY_SAMPLES,\n            }\n        )\n    elif label_mode in {"raw_return", "return", "mse_return"}:\n        lower, upper = np.percentile(y, [1, 99])\n        y = np.clip(y, lower, upper).astype(np.float32)\n        metadata.update(\n            {\n                f"{stage}_label_type": "next_day_raw_return_winsor_1_99",\n                f"{stage}_winsor_lower": float(lower),\n                f"{stage}_winsor_upper": float(upper),\n            }\n        )\n    else:\n        raise ValueError(f"未知 DIFFMLANET_LABEL_MODE={LABEL_MODE!r}，可选 daily_rank/raw_return。")\n\n    metadata.update(\n        {\n            f"{stage}_sample_count_after_label": int(len(y)),\n            f"{stage}_label_mean": float(np.mean(y)),\n            f"{stage}_label_std": float(np.std(y)),\n            f"{stage}_label_min": float(np.min(y)),\n            f"{stage}_label_max": float(np.max(y)),\n        }\n    )\n    return X.astype(np.float32, copy=False), y.astype(np.float32, copy=False), index_df, metadata\n\n\ndef _build_loss_fn() -> nn.Module:\n    if LOSS_NAME in {"smooth_l1", "huber"}:\n        return nn.SmoothL1Loss(beta=SMOOTH_L1_BETA)\n    if LOSS_NAME in {"mse", "mse_loss"}:\n        return nn.MSELoss()\n    raise ValueError(f"未知 DIFFMLANET_LOSS={LOSS_NAME!r}，可选 smooth_l1/mse。")\n\n\ndef _is_val_date(index_df: pd.DataFrame) -> np.ndarray:\n    if not USE_VALIDATION:\n        return np.zeros(len(index_df), dtype=bool)\n    dates = pd.to_datetime(index_df["date"], errors="coerce").dt.normalize()\n    start = pd.Timestamp(VALID_START).normalize()\n    end = pd.Timestamp(VALID_END).normalize()\n    return ((dates >= start) & (dates <= end)).to_numpy()\n\n\ndef _append_train_val_parts(\n    X_tmp: np.ndarray,\n    y_tmp: np.ndarray,\n    index_tmp: pd.DataFrame,\n    *,\n    X_train_parts: list[np.ndarray],\n    y_train_parts: list[np.ndarray],\n    index_train_parts: list[pd.DataFrame],\n    X_val_parts: list[np.ndarray],\n    y_val_parts: list[np.ndarray],\n    index_val_parts: list[pd.DataFrame],\n) -> None:\n    val_mask = _is_val_date(index_tmp)\n    train_mask = ~val_mask\n    if bool(train_mask.any()):\n        X_train_parts.append(X_tmp[train_mask])\n        y_train_parts.append(y_tmp[train_mask])\n        index_train_parts.append(index_tmp.loc[train_mask].reset_index(drop=True))\n    if bool(val_mask.any()):\n        X_val_parts.append(X_tmp[val_mask])\n        y_val_parts.append(y_tmp[val_mask])\n        index_val_parts.append(index_tmp.loc[val_mask].reset_index(drop=True))\n\n\ndef _concat_or_empty(parts: list[np.ndarray], *, shape_tail: tuple[int, ...], dtype=np.float32) -> np.ndarray:\n    if parts:\n        return np.concatenate(parts).astype(dtype, copy=False)\n    return np.empty((0, *shape_tail), dtype=dtype)\n\n\ndef _concat_index(parts: list[pd.DataFrame]) -> pd.DataFrame:\n    if parts:\n        return pd.concat(parts, ignore_index=True)\n    return pd.DataFrame(columns=["date", "instrument"])\n\n\ndef _compute_stats(X_train: np.ndarray) -> tuple[np.ndarray, np.ndarray]:\n    flat = X_train.reshape(-1, len(FEATURE_COLS))\n    mean = flat.mean(axis=0, dtype=np.float64).astype(np.float32)\n    std = (flat.std(axis=0, dtype=np.float64) + 1e-6).astype(np.float32)\n    std[std < 1e-6] = 1.0\n    return mean, std\n\n\ndef _apply_stats_inplace(X: np.ndarray, stats: tuple[np.ndarray, np.ndarray]) -> np.ndarray:\n    if len(X) == 0:\n        return X.astype(np.float32, copy=False)\n    mean, std = stats\n    X -= mean.reshape(1, 1, -1)\n    X /= std.reshape(1, 1, -1)\n    return X.astype(np.float32, copy=False)\n\n\ndef _finalize_train_val_data(\n    X_train_parts: list[np.ndarray],\n    y_train_parts: list[np.ndarray],\n    index_train_parts: list[pd.DataFrame],\n    X_val_parts: list[np.ndarray],\n    y_val_parts: list[np.ndarray],\n    index_val_parts: list[pd.DataFrame],\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, np.ndarray, np.ndarray, pd.DataFrame, tuple[np.ndarray, np.ndarray]]:\n    if not X_train_parts:\n        raise RuntimeError("训练区间没有构造出任何训练样本；请检查 VALID_START/VALID_END 是否把全部数据都划成验证集。")\n\n    X_train = _concat_or_empty(X_train_parts, shape_tail=(SEQ_LEN, len(FEATURE_COLS)))\n    y_train = _concat_or_empty(y_train_parts, shape_tail=(), dtype=np.float32)\n    index_train = _concat_index(index_train_parts)\n\n    X_val = _concat_or_empty(X_val_parts, shape_tail=(SEQ_LEN, len(FEATURE_COLS)))\n    y_val = _concat_or_empty(y_val_parts, shape_tail=(), dtype=np.float32)\n    index_val = _concat_index(index_val_parts)\n\n    stats = _compute_stats(X_train)\n    X_train = _apply_stats_inplace(X_train, stats)\n    X_val = _apply_stats_inplace(X_val, stats)\n    return X_train, y_train, index_train, X_val, y_val, index_val, stats\n\n\ndef load_training_samples(\n    data_path: str,\n    *,\n    train_start: str,\n    train_end: str,\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, np.ndarray, np.ndarray, pd.DataFrame, tuple[np.ndarray, np.ndarray]]:\n    """读取本地 parquet 并构造训练/验证样本。\n\n    合规说明：这里只使用原始字段窗口，除允许的缺失填充、按字段 log1p、标准化外，\n    不构造跨字段算子、滚动统计、人工因子、降维特征。\n    """\n    files = discover_parquet_files(data_path)\n    if len(files) < 2:\n        raise RuntimeError("训练至少需要两个 parquet 文件，以便计算下一交易日收益标签")\n\n    instruments = _select_local_instruments(files[0])\n    start_ts = pd.Timestamp(train_start).normalize()\n    end_ts = pd.Timestamp(train_end).normalize()\n\n    X_train_parts: list[np.ndarray] = []\n    y_train_parts: list[np.ndarray] = []\n    index_train_parts: list[pd.DataFrame] = []\n    X_val_parts: list[np.ndarray] = []\n    y_val_parts: list[np.ndarray] = []\n    index_val_parts: list[pd.DataFrame] = []\n\n    for file_index, path in enumerate(files):\n        current = to_canonical(pd.read_parquet(path), is_local=True)\n        current_days = current["date"].dt.normalize()\n        sample_start = max(current_days.min(), start_ts)\n        sample_end = min(current_days.max(), end_ts)\n        if sample_start > sample_end:\n            continue\n\n        if file_index + 1 < len(files):\n            next_df = to_canonical(pd.read_parquet(files[file_index + 1]), is_local=True)\n            pair = pd.concat([current, next_df], ignore_index=True)\n        else:\n            pair = current\n\n        pair_end_day = pair["date"].dt.normalize().max()\n        try:\n            X_tmp, y_tmp, index_tmp, _ = build_samples(\n                pair,\n                start_date=f"{sample_start:%Y-%m-%d} 00:00:00",\n                end_date=f"{pair_end_day:%Y-%m-%d} 23:59:59",\n                mode="train",\n                instruments=instruments,\n                normalize=False,\n            )\n        except RuntimeError as exc:\n            log("训练样本跳过", file=f"{file_index + 1}/{len(files)}", reason=str(exc))\n            continue\n\n        index_dates = pd.to_datetime(index_tmp["date"]).dt.normalize()\n        keep = ((index_dates >= sample_start) & (index_dates <= sample_end)).to_numpy()\n        if not bool(keep.any()):\n            continue\n\n        X_tmp = X_tmp[keep]\n        y_tmp = y_tmp[keep]\n        index_tmp = index_tmp.loc[keep].reset_index(drop=True)\n        _append_train_val_parts(\n            X_tmp,\n            y_tmp,\n            index_tmp,\n            X_train_parts=X_train_parts,\n            y_train_parts=y_train_parts,\n            index_train_parts=index_train_parts,\n            X_val_parts=X_val_parts,\n            y_val_parts=y_val_parts,\n            index_val_parts=index_val_parts,\n        )\n        log(\n            "训练样本读取",\n            file=f"{file_index + 1}/{len(files)}",\n            start=str(sample_start.date()),\n            end=str(sample_end.date()),\n            samples=int(keep.sum()),\n        )\n\n    return _finalize_train_val_data(\n        X_train_parts,\n        y_train_parts,\n        index_train_parts,\n        X_val_parts,\n        y_val_parts,\n        index_val_parts,\n    )\n\n\ndef _date_batches(index_df: pd.DataFrame, *, shuffle: bool, seed: int) -> list[np.ndarray]:\n    frame = index_df.copy().reset_index(drop=True)\n    frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.normalize()\n    frame["_row"] = np.arange(len(frame), dtype=np.int64)\n    batches = [group["_row"].to_numpy(dtype=np.int64) for _, group in frame.groupby("date", sort=True)]\n    batches = [batch for batch in batches if len(batch) >= MIN_IC_DAY_SAMPLES]\n    if shuffle:\n        rng = np.random.default_rng(seed)\n        rng.shuffle(batches)\n    return batches\n\n\ndef _negative_corr_loss(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:\n    pred = pred.float().view(-1)\n    target = target.float().view(-1)\n    if pred.numel() < 2:\n        return pred.new_tensor(0.0)\n    pred = pred - pred.mean()\n    target = target - target.mean()\n    denom = torch.sqrt(torch.sum(pred * pred) + 1e-8) * torch.sqrt(torch.sum(target * target) + 1e-8)\n    corr = torch.sum(pred * target) / denom.clamp_min(1e-8)\n    return -corr\n\n\ndef _predict_numpy(model: nn.Module, X: np.ndarray, *, device: torch.device) -> np.ndarray:\n    if len(X) == 0:\n        return np.empty((0,), dtype=np.float64)\n    output: list[np.ndarray] = []\n    model.eval()\n    with torch.inference_mode():\n        for start in range(0, len(X), BATCH):\n            batch = torch.from_numpy(X[start:start + BATCH]).to(device, non_blocking=True)\n            output.append(model(batch).detach().cpu().numpy())\n    return np.concatenate(output).astype(np.float64)\n\n\ndef _rankic_metrics(pred: np.ndarray, y: np.ndarray, index_df: pd.DataFrame) -> dict[str, Any]:\n    if len(pred) == 0 or len(y) == 0:\n        return {"rankic_mean": None, "rankic_std": None, "rankic_ir": None, "rankic_days": 0}\n\n    frame = index_df.copy().reset_index(drop=True)\n    frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.normalize()\n    frame["_pred"] = np.asarray(pred, dtype=np.float64)\n    frame["_y"] = np.asarray(y, dtype=np.float64)\n    frame = frame.replace([np.inf, -np.inf], np.nan).dropna(subset=["date", "_pred", "_y"])\n\n    values: list[float] = []\n    for _, group in frame.groupby("date", sort=True):\n        if len(group) < MIN_IC_DAY_SAMPLES:\n            continue\n        pred_rank = group["_pred"].rank(method="average").to_numpy(dtype=np.float64)\n        true_rank = group["_y"].rank(method="average").to_numpy(dtype=np.float64)\n        pred_rank -= pred_rank.mean()\n        true_rank -= true_rank.mean()\n        denom = np.sqrt(np.sum(pred_rank ** 2)) * np.sqrt(np.sum(true_rank ** 2))\n        if denom > 1e-12:\n            values.append(float(np.sum(pred_rank * true_rank) / denom))\n\n    if not values:\n        return {"rankic_mean": None, "rankic_std": None, "rankic_ir": None, "rankic_days": 0}\n    arr = np.asarray(values, dtype=np.float64)\n    mean = float(arr.mean())\n    std = float(arr.std(ddof=0))\n    return {\n        "rankic_mean": mean,\n        "rankic_std": std,\n        "rankic_ir": float(mean / (std + 1e-12)),\n        "rankic_days": int(len(arr)),\n    }\n\n\ndef _evaluate_rankic(\n    model: nn.Module,\n    X_val: np.ndarray,\n    y_val: np.ndarray,\n    index_val: pd.DataFrame,\n    *,\n    device: torch.device,\n) -> dict[str, Any]:\n    pred = _predict_numpy(model, X_val, device=device)\n    return _rankic_metrics(pred, y_val, index_val)\n\n\ndef _fit_and_save(\n    X_train: np.ndarray,\n    y_train: np.ndarray,\n    index_train: pd.DataFrame,\n    X_val: np.ndarray,\n    y_val: np.ndarray,\n    index_val: pd.DataFrame,\n    stats: tuple[np.ndarray, np.ndarray],\n    *,\n    model_path: str | os.PathLike,\n    metadata: dict[str, Any],\n) -> str:\n    seed_everything(SEED)\n    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")\n    config = model_config()\n\n    X_train, y_train, index_train, train_label_metadata = _prepare_labels(X_train, y_train, index_train, stage="train")\n    val_label_metadata: dict[str, Any] = {}\n    has_validation = USE_VALIDATION and len(X_val) > 0 and len(y_val) > 0\n    if has_validation:\n        X_val, y_val, index_val, val_label_metadata = _prepare_labels(X_val, y_val, index_val, stage="val")\n        has_validation = len(X_val) > 0\n\n    model = build_model(config).to(device)\n    parameter_count = validate_model_size(model)\n    log(\n        "训练数据准备完成",\n        X_shape=str(X_train.shape),\n        y_shape=str(y_train.shape),\n        val_shape=str(X_val.shape) if has_validation else "None",\n        trainable_params=parameter_count,\n        device=str(device),\n        label_mode=LABEL_MODE,\n        loss=LOSS_NAME,\n        ic_alpha=IC_LOSS_ALPHA,\n        y_mean=round(float(np.mean(y_train)), 6),\n        y_std=round(float(np.std(y_train)), 6),\n    )\n\n    train_batches = _date_batches(index_train, shuffle=True, seed=SEED)\n    if not train_batches:\n        raise RuntimeError("按日期 batch 构造失败：没有满足 MIN_IC_DAY_SAMPLES 的训练日期。")\n    log("日期 batch 构造完成", train_days=len(train_batches), min_day_samples=MIN_IC_DAY_SAMPLES)\n\n    optimizer = torch.optim.AdamW(\n        model.parameters(),\n        lr=LR,\n        weight_decay=float(os.environ.get("DIFFMLANET_WEIGHT_DECAY", "0.0005")),\n    )\n    loss_fn = _build_loss_fn()\n\n    best_score = -1e18\n    best_epoch = 0\n    best_state: dict[str, torch.Tensor] | None = None\n    best_metrics: dict[str, Any] = {}\n\n    for epoch in range(EPOCHS):\n        started = time.time()\n        model.train()\n        total_loss = 0.0\n        total_reg = 0.0\n        total_ic = 0.0\n        total_diff = 0.0\n        batches = 0\n        epoch_batches = _date_batches(index_train, shuffle=True, seed=SEED + epoch)\n        for batch_index in epoch_batches:\n            X_batch = torch.from_numpy(X_train[batch_index]).to(device, non_blocking=True)\n            y_batch = torch.from_numpy(y_train[batch_index]).to(device, non_blocking=True)\n            optimizer.zero_grad(set_to_none=True)\n            if config.diffusion_enabled:\n                pred, diffusion_loss = model(X_batch, return_diffusion_loss=True)\n            else:\n                pred = model(X_batch)\n                diffusion_loss = pred.new_tensor(0.0)\n            reg_loss = loss_fn(pred, y_batch)\n            ic_loss = _negative_corr_loss(pred, y_batch)\n            loss = reg_loss + float(config.lambda_diff) * diffusion_loss + IC_LOSS_ALPHA * ic_loss\n            loss.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            optimizer.step()\n\n            total_loss += float(loss.item())\n            total_reg += float(reg_loss.item())\n            total_ic += float(ic_loss.item())\n            total_diff += float(diffusion_loss.item())\n            batches += 1\n\n        epoch_info = {\n            "epoch": epoch + 1,\n            "loss": round(total_loss / max(batches, 1), 8),\n            "reg": round(total_reg / max(batches, 1), 8),\n            "ic_loss": round(total_ic / max(batches, 1), 8),\n            "diff": round(total_diff / max(batches, 1), 8),\n            "elapsed": round(time.time() - started, 2),\n        }\n\n        if has_validation:\n            metrics = _evaluate_rankic(model, X_val, y_val, index_val, device=device)\n            rankic_mean = metrics.get("rankic_mean")\n            epoch_info.update(\n                {\n                    "val_rankic": None if rankic_mean is None else round(float(rankic_mean), 8),\n                    "val_ir": None if metrics.get("rankic_ir") is None else round(float(metrics["rankic_ir"]), 6),\n                    "val_days": metrics.get("rankic_days", 0),\n                }\n            )\n            score = -1e18 if rankic_mean is None else float(rankic_mean)\n            if score > best_score:\n                best_score = score\n                best_epoch = epoch + 1\n                best_metrics = metrics\n                best_state = {key: value.detach().cpu().clone() for key, value in model.state_dict().items()}\n                epoch_info["best"] = True\n        else:\n            best_epoch = epoch + 1\n            best_state = {key: value.detach().cpu().clone() for key, value in model.state_dict().items()}\n            best_score = 0.0\n            best_metrics = {}\n\n        log("epoch 完成", **epoch_info)\n\n    if best_state is not None:\n        model.load_state_dict(best_state)\n\n    metadata = dict(metadata)\n    metadata.update(train_label_metadata)\n    metadata.update(val_label_metadata)\n    metadata.update(\n        {\n            "model_family": "standalone_re_mlanet4_diffusion_rankic_best_v3",\n            "sample_count": int(len(y_train)),\n            "val_sample_count": int(len(y_val)) if has_validation else 0,\n            "trainable_params": int(parameter_count),\n            "loss_name": LOSS_NAME,\n            "smooth_l1_beta": SMOOTH_L1_BETA if LOSS_NAME in {"smooth_l1", "huber"} else None,\n            "ic_loss_alpha": float(IC_LOSS_ALPHA),\n            "min_ic_day_samples": int(MIN_IC_DAY_SAMPLES),\n            "use_validation": bool(has_validation),\n            "valid_start": VALID_START if has_validation else None,\n            "valid_end": VALID_END if has_validation else None,\n            "best_epoch": int(best_epoch),\n            "best_val_rankic_mean": best_metrics.get("rankic_mean"),\n            "best_val_rankic_ir": best_metrics.get("rankic_ir"),\n            "best_val_rankic_days": best_metrics.get("rankic_days"),\n            "score_postprocess": "daily_rank_pct_scaled_to_minus1_1",\n            "input_rule_note": "raw_fields_only; missing_fill_log1p_standardization_allowed; no_handcrafted_factors",\n        }\n    )\n    saved = save_model_json(model, stats=stats, model_path=model_path, config=config, metadata=metadata)\n    log("模型已保存", path=saved, best_epoch=best_epoch, best_val_rankic=best_metrics.get("rankic_mean"))\n    return saved\n\n\ndef train_and_save_local(\n    data_path: str = LOCAL_DATA_PATH,\n    model_path: str | os.PathLike = MODEL_PATH,\n    train_start: str = LOCAL_TRAIN_START,\n    train_end: str = LOCAL_TRAIN_END,\n) -> str:\n    is_smoke_test = (\n        pd.Timestamp(train_start).normalize() > pd.Timestamp(PUBLIC_TRAIN_START).normalize()\n        or pd.Timestamp(train_end).normalize() < pd.Timestamp(PUBLIC_TRAIN_END).normalize()\n        or MAX_LOCAL_INSTRUMENTS > 0\n    )\n    log(\n        "本地训练开始",\n        data_path=data_path,\n        start=train_start,\n        end=train_end,\n        validation=USE_VALIDATION,\n        valid_start=VALID_START if USE_VALIDATION else None,\n        valid_end=VALID_END if USE_VALIDATION else None,\n        smoke_test=is_smoke_test,\n    )\n    X_train, y_train, index_train, X_val, y_val, index_val, stats = load_training_samples(\n        data_path,\n        train_start=train_start,\n        train_end=train_end,\n    )\n    return _fit_and_save(\n        X_train,\n        y_train,\n        index_train,\n        X_val,\n        y_val,\n        index_val,\n        stats,\n        model_path=model_path,\n        metadata={\n            "train_start": train_start,\n            "train_end": train_end,\n            "data_path": str(data_path),\n            "smoke_test": is_smoke_test,\n            "instrument_limit": MAX_LOCAL_INSTRUMENTS,\n        },\n    )\n\n\ndef _require_dai() -> None:\n    if dai is None:\n        raise ModuleNotFoundError("云端训练需要 BigQuant dai 环境")\n\n\ndef _pool(start_date: str, end_date: str) -> list[str]:\n    _require_dai()\n    frame = dai.query(\n        "SELECT DISTINCT instrument FROM bigalpha_2026_instruments",\n        filters={"date": [start_date, end_date]},\n    ).df()\n    instruments = sorted(frame["instrument"].dropna().astype(str).unique().tolist())\n    if MAX_TRAIN_INSTRUMENTS > 0:\n        instruments = instruments[:MAX_TRAIN_INSTRUMENTS]\n    return instruments\n\n\ndef _query_cloud_samples(\n    table: str,\n    train_start: str,\n    train_end: str,\n) -> tuple[np.ndarray, np.ndarray, pd.DataFrame, np.ndarray, np.ndarray, pd.DataFrame, tuple[np.ndarray, np.ndarray]]:\n    bar_start, bar_end = full_day_bounds(train_start, train_end)\n    instruments = _pool(train_start, train_end)\n    sql = f"SELECT date, instrument, {\', \'.join(FEATURE_COLS)} FROM {table} ORDER BY instrument, date"\n\n    X_train_parts: list[np.ndarray] = []\n    y_train_parts: list[np.ndarray] = []\n    index_train_parts: list[pd.DataFrame] = []\n    X_val_parts: list[np.ndarray] = []\n    y_val_parts: list[np.ndarray] = []\n    index_val_parts: list[pd.DataFrame] = []\n\n    for offset in range(0, len(instruments), TRAIN_CHUNK):\n        chunk = instruments[offset:offset + TRAIN_CHUNK]\n        raw = dai.query(sql, filters={"date": [bar_start, bar_end], "instrument": chunk}).df()\n        if raw.empty:\n            continue\n        canonical = to_canonical(raw, is_local=False)\n        try:\n            X_chunk, y_chunk, index_chunk, _ = build_samples(\n                canonical,\n                start_date=bar_start,\n                end_date=bar_end,\n                mode="train",\n                instruments=chunk,\n                normalize=False,\n            )\n        except RuntimeError as exc:\n            log("云端训练分块跳过", instruments=f"{min(offset + len(chunk), len(instruments))}/{len(instruments)}", reason=str(exc))\n            continue\n        _append_train_val_parts(\n            X_chunk,\n            y_chunk,\n            index_chunk,\n            X_train_parts=X_train_parts,\n            y_train_parts=y_train_parts,\n            index_train_parts=index_train_parts,\n            X_val_parts=X_val_parts,\n            y_val_parts=y_val_parts,\n            index_val_parts=index_val_parts,\n        )\n        log("云端训练数据", instruments=f"{min(offset + len(chunk), len(instruments))}/{len(instruments)}", samples=len(y_chunk))\n\n    return _finalize_train_val_data(\n        X_train_parts,\n        y_train_parts,\n        index_train_parts,\n        X_val_parts,\n        y_val_parts,\n        index_val_parts,\n    )\n\n\ndef train_and_save(\n    datasources: dict,\n    model_path: str | os.PathLike = MODEL_PATH,\n    train_start: str = PUBLIC_TRAIN_START,\n    train_end: str = PUBLIC_TRAIN_END,\n) -> str:\n    _require_dai()\n    table = datasources.get("bar5m") or datasources.get("bar1m")\n    if table is None:\n        raise KeyError("datasources 需要包含 bar5m；兼容旧写法时也可包含 bar1m")\n    X_train, y_train, index_train, X_val, y_val, index_val, stats = _query_cloud_samples(table, train_start, train_end)\n    return _fit_and_save(\n        X_train,\n        y_train,\n        index_train,\n        X_val,\n        y_val,\n        index_val,\n        stats,\n        model_path=model_path,\n        metadata={\n            "train_start": train_start,\n            "train_end": train_end,\n            "table": table,\n            "smoke_test": MAX_TRAIN_INSTRUMENTS > 0,\n            "instrument_limit": MAX_TRAIN_INSTRUMENTS,\n        },\n    )\n\n\ndef _platform_datasources() -> dict | None:\n    g = globals()\n    if "datasources" in g:\n        value = g["datasources"]\n        return {"bar5m": value} if isinstance(value, str) else value\n    if "datasource" in g:\n        return {"bar5m": g["datasource"]} if isinstance(g["datasource"], str) else g["datasource"]\n    return None\n\n\ndef _platform_train_dates() -> tuple[str, str]:\n    g = globals()\n    start_value = g.get("train_start_date", g.get("train_start", PUBLIC_TRAIN_START))\n    end_value = g.get("train_end_date", g.get("train_end", PUBLIC_TRAIN_END))\n    return str(start_value), str(end_value)\n\n\nif __name__ == "__main__":\n    platform_datasources = _platform_datasources()\n    force_local = os.environ.get("DIFFMLANET_USE_LOCAL") == "1"\n    force_cloud = os.environ.get("DIFFMLANET_USE_CLOUD") == "1"\n\n    if force_local or (platform_datasources is None and not force_cloud):\n        if platform_datasources is None and not force_local:\n            log("未检测到平台 datasources，默认使用本地 parquet 训练")\n        model_path = train_and_save_local()\n    else:\n        if platform_datasources is None:\n            platform_datasources = {\n                "bar5m": os.environ.get("DIFFMLANET_CLOUD_BAR5M_TABLE", "bigalpha_2026_stock_bar5m")\n            }\n            log("强制云端训练，使用默认云端训练数据源", datasources=platform_datasources)\n\n        train_start_value, train_end_value = _platform_train_dates()\n        model_path = train_and_save(\n            platform_datasources,\n            model_path=MODEL_PATH,\n            train_start=train_start_value,\n            train_end=train_end_value,\n        )\n    print(model_path)\n'


def log(message: str, **kwargs: Any) -> None:
    extra = " ".join(f"{key}={value}" for key, value in kwargs.items())
    print(f"[82fusion][train] {message}" + (f" {extra}" if extra else ""))


def _set_env_temporarily(overrides: dict[str, str | os.PathLike]):
    class EnvGuard:
        def __enter__(self):
            self.old = {key: os.environ.get(key) for key in overrides}
            for key, value in overrides.items():
                os.environ[key] = str(value)
            return self

        def __exit__(self, exc_type, exc, tb):
            for key, value in self.old.items():
                if value is None:
                    os.environ.pop(key, None)
                else:
                    os.environ[key] = value
            return False

    return EnvGuard()


def _load_embedded_module(name: str, source: str, *, model_path: Path, epochs: int) -> types.ModuleType:
    """把 1m/5m 训练源码加载到独立 module namespace。"""
    module = types.ModuleType(name)
    module.__file__ = str(ROOT / f"_embedded_{name}.py")
    module.__dict__["__name__"] = name
    # dataclasses.dataclass 在处理类型标注时会通过 sys.modules[cls.__module__]
    # 找模块命名空间；必须在 exec 之前注册，否则会出现 NoneType.__dict__ 报错。
    sys.modules[name] = module
    # 这些变量在子训练源码 import 时读取，所以要在 exec 前设置。
    env = {
        "DIFFMLANET_MODEL_PATH": model_path,
        "DIFFMLANET_EPOCHS": str(epochs),
    }
    with _set_env_temporarily(env):
        exec(compile(source, module.__file__, "exec"), module.__dict__)
    return module


def _load_json(path: Path) -> dict[str, Any]:
    if not path.exists():
        raise FileNotFoundError(f"找不到子模型文件: {path}")
    return json.loads(path.read_text(encoding="utf-8"))


def _check_submodel(payload: dict[str, Any], *, freq: str, schema: str) -> None:
    actual_schema = payload.get("feature_schema_version")
    if actual_schema != schema:
        raise RuntimeError(f"{freq} 子模型 schema 不对: {actual_schema}，期望: {schema}")
    if payload.get("metadata", {}).get("smoke_test"):
        raise RuntimeError(f"{freq} 子模型是 smoke_test 小样本权重，不能正式提交")
    missing = [key for key in ["model_cfg", "feature_cols", "stats", "state_dict"] if key not in payload]
    if missing:
        raise RuntimeError(f"{freq} 子模型缺少字段: {missing}")


def _build_fusion_payload(model_1m: dict[str, Any], model_5m: dict[str, Any]) -> dict[str, Any]:
    _check_submodel(model_1m, freq="1m", schema="e2e_bar1m_full_3level_v1")
    _check_submodel(model_5m, freq="5m", schema="e2e_bar5m_full_3level_v1")
    if abs((WEIGHT_1M + WEIGHT_5M) - 1.0) > 1e-8:
        raise RuntimeError(f"融合权重之和必须为 1，当前={WEIGHT_1M + WEIGHT_5M}")
    return {
        "model_name": "rank_fusion_re_dm_1m_5m_82_full_train",
        "fusion_type": "daily_rank_weighted_sum",
        "weights": {"1m": WEIGHT_1M, "5m": WEIGHT_5M},
        "models": {"1m": model_1m, "5m": model_5m},
        "metadata": {
            "description": "full retrain 1m + 5m daily rank weighted fusion",
            "default_weight_1m": WEIGHT_1M,
            "default_weight_5m": WEIGHT_5M,
            "epochs_1m": EPOCHS_1M,
            "epochs_5m": EPOCHS_5M,
            "time_budget_seconds": TIME_BUDGET_SECONDS,
            "model_1m_family": model_1m.get("metadata", {}).get("model_family"),
            "model_5m_family": model_5m.get("metadata", {}).get("model_family"),
        },
    }


def _normalize_datasources(datasources: dict | str | None) -> dict[str, str]:
    if datasources is None:
        return {
            "bar1m": os.environ.get("FUSION_CLOUD_BAR1M_TABLE", "bigalpha_2026_stock_bar1m"),
            "bar5m": os.environ.get("FUSION_CLOUD_BAR5M_TABLE", "bigalpha_2026_stock_bar5m"),
        }
    if isinstance(datasources, str):
        return {
            "bar1m": datasources,
            "bar5m": os.environ.get("FUSION_CLOUD_BAR5M_TABLE", "bigalpha_2026_stock_bar5m"),
        }
    result = dict(datasources)
    result.setdefault("bar1m", os.environ.get("FUSION_CLOUD_BAR1M_TABLE", "bigalpha_2026_stock_bar1m"))
    result.setdefault("bar5m", os.environ.get("FUSION_CLOUD_BAR5M_TABLE", "bigalpha_2026_stock_bar5m"))
    return result


def _write_payload(payload: dict[str, Any], model_path: str | os.PathLike = OUTPUT_PATH) -> str:
    output = Path(model_path)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    log("融合模型已保存", path=output, weight_1m=WEIGHT_1M, weight_5m=WEIGHT_5M)
    return str(output)


def train_and_save(
    datasources: dict | str | None = None,
    model_path: str | os.PathLike = OUTPUT_PATH,
    train_start: str = "2019-01-01",
    train_end: str = "2023-12-31 23:59:59",
) -> str:
    """云端/平台训练入口：从官方 bar1m + bar5m 重训两个子模型。"""
    started = time.time()
    TEMP_DIR.mkdir(parents=True, exist_ok=True)
    ds = _normalize_datasources(datasources)
    path_1m = TEMP_DIR / "submodel_1m.json"
    path_5m = TEMP_DIR / "submodel_5m.json"

    log("开始训练 1m 子模型", epochs=EPOCHS_1M, table=ds["bar1m"])
    module_1m = _load_embedded_module("fusion_subtrain_1m", SOURCE_1M, model_path=path_1m, epochs=EPOCHS_1M)
    module_1m.train_and_save({"bar1m": ds["bar1m"]}, model_path=path_1m, train_start=train_start, train_end=train_end)
    elapsed = time.time() - started
    log("1m 子模型完成", elapsed=round(elapsed, 2))

    if elapsed > TIME_BUDGET_SECONDS * 0.75:
        log("警告：1m 训练耗时已接近总预算，5m 仍会继续，但可能超过4小时", elapsed=round(elapsed, 2))

    log("开始训练 5m 子模型", epochs=EPOCHS_5M, table=ds["bar5m"])
    module_5m = _load_embedded_module("fusion_subtrain_5m", SOURCE_5M, model_path=path_5m, epochs=EPOCHS_5M)
    module_5m.train_and_save({"bar5m": ds["bar5m"]}, model_path=path_5m, train_start=train_start, train_end=train_end)
    elapsed = time.time() - started
    log("5m 子模型完成", elapsed=round(elapsed, 2))

    payload = _build_fusion_payload(_load_json(path_1m), _load_json(path_5m))
    return _write_payload(payload, model_path)


def train_and_save_local(
    model_path: str | os.PathLike = OUTPUT_PATH,
    train_start: str = "2019-01-01",
    train_end: str = "2023-12-31 23:59:59",
) -> str:
    """本地训练入口：读取 local_data/e2e_bar1m_* 和 e2e_bar5m_*。"""
    started = time.time()
    TEMP_DIR.mkdir(parents=True, exist_ok=True)
    path_1m = TEMP_DIR / "submodel_1m.json"
    path_5m = TEMP_DIR / "submodel_5m.json"
    data_1m = os.environ.get("FUSION_LOCAL_DATA_1M", str(PROJECT_ROOT / "local_data/e2e_bar1m_train_2019_2023"))
    data_5m = os.environ.get("FUSION_LOCAL_DATA_5M", str(PROJECT_ROOT / "local_data/e2e_bar5m_train_2019_2023"))

    log("开始本地训练 1m 子模型", epochs=EPOCHS_1M, data=data_1m)
    module_1m = _load_embedded_module("fusion_subtrain_1m", SOURCE_1M, model_path=path_1m, epochs=EPOCHS_1M)
    module_1m.train_and_save_local(data_path=data_1m, model_path=path_1m, train_start=train_start, train_end=train_end)
    log("1m 子模型完成", elapsed=round(time.time() - started, 2))

    log("开始本地训练 5m 子模型", epochs=EPOCHS_5M, data=data_5m)
    module_5m = _load_embedded_module("fusion_subtrain_5m", SOURCE_5M, model_path=path_5m, epochs=EPOCHS_5M)
    module_5m.train_and_save_local(data_path=data_5m, model_path=path_5m, train_start=train_start, train_end=train_end)
    log("5m 子模型完成", elapsed=round(time.time() - started, 2))

    payload = _build_fusion_payload(_load_json(path_1m), _load_json(path_5m))
    return _write_payload(payload, model_path)


def _platform_datasources() -> dict | None:
    g = globals()
    if "datasources" in g:
        return _normalize_datasources(g["datasources"])
    if "datasource" in g:
        return _normalize_datasources(g["datasource"])
    return None


def _platform_train_dates() -> tuple[str, str]:
    g = globals()
    start_value = g.get("train_start_date", g.get("train_start", "2019-01-01"))
    end_value = g.get("train_end_date", g.get("train_end", "2023-12-31 23:59:59"))
    return str(start_value), str(end_value)


def main() -> str:
    platform_datasources = _platform_datasources()
    train_start, train_end = _platform_train_dates()
    force_local = os.environ.get("FUSION_USE_LOCAL") == "1"
    force_cloud = os.environ.get("FUSION_USE_CLOUD") == "1"
    if force_local or (platform_datasources is None and not force_cloud):
        log("使用本地数据训练完整融合模型")
        return train_and_save_local(model_path=OUTPUT_PATH, train_start=train_start, train_end=train_end)
    log("使用云端数据训练完整融合模型")
    return train_and_save(platform_datasources, model_path=OUTPUT_PATH, train_start=train_start, train_end=train_end)


if __name__ == "__main__":
    main()
